def add(n, story, picks): STORIES[n] = {'story': story, 'picks': picks}

add(851, [
'''רובי וויליאמס הצטרף לטייק דאט, להקת הבנים המצליחה ביותר בבריטניה של תחילת שנות התשעים, כשהיה רק בן שש עשרה. הוא היה הצעיר, השובב והמצחיק בחבורה, וב־1995, אחרי חיכוכים רבים, עזב את הלהקה. רבים חשבו שהקריירה שלו נגמרה. Life Thru a Lens, אלבום הסולו הראשון שלו, יצא בסתיו 1997, ובהתחלה נמכר לאט ובאכזבה. ואז, בסוף השנה, יצא השיר Angels, והכל השתנה: האלבום טיפס למקום הראשון במצעד הבריטי, ורובי הפך לכוכב הגדול ביותר במדינה.''',
'''את רוב השירים כתב רובי יחד עם גאי צ׳יימברס, מוזיקאי מנוסה שהבין בדיוק איך להפוך את האנרגיה הפרועה שלו לשירי פופ רוק גדולים, עם גיטרות, פסנתר, כלי מיתר ופזמונים שנועדו לאצטדיונים. ההשפעה של הבריטפופ, של אואזיס ושל להקות הרוק הבריטיות של שנות השבעים ברורה. Angels היא בלדה רחבה ומרגשת, שמתחילה בשקט עם פסנתר ונבנית לפזמון אדיר שכל קהל שר. Let Me Entertain You הוא שיר רוק מתגרה ושמח, שהפך לשיר הפתיחה הקבוע בהופעות שלו. Old Before I Die, הסינגל הראשון מהאלבום, הוא שיר אנרגטי עם גיטרות ותופים, על הרצון לחיות מהר.''',
'''Angels נבחר שנים אחר כך, בטקס פרסי בריט, לשיר הבריטי הטוב ביותר של רבע המאה האחרונה, ורובי הפך לאחד הזמרים המצליחים בתולדות בריטניה, עם הופעות ענק מול מאות אלפי אנשים. האלבום הזה הוא הרגע שבו הבחור השובב מלהקת הבנים הוכיח שהוא אמן אמיתי, עם הומור, כריזמה וקול חם.''',
'''שמעו את Angels, ושימו לב איך השיר נבנה לאט מפסנתר שקט לפזמון ענק. ואחר כך השוו את Let Me Entertain You ל־(What's the Story) Morning Glory? של אואזיס (אלבום 804), שיצא שנתיים קודם.''',
], [
('Angels', 'בלדה רחבה ומרגשת, מפסנתר שקט לפזמון אדיר שכל קהל שר.'),
('Let Me Entertain You', 'רוק מתגרה ושמח, שיר הפתיחה הקבוע בכל ההופעות שלו.'),
('Old Before I Die', 'שיר אנרגטי עם גיטרות ותופים, על הרצון לחיות מהר.'),
])

add(852, [
'''מראיה קארי הייתה כבר בתחילת שנות התשעים אחת הזמרות המצליחות בעולם, עם קול בעל טווח עצום, שמגיע עד לצלילים גבוהים במיוחד, ובלדות פופ מלוטשות שכבשו את המצעדים. אבל היא הרגישה כלואה: היא הייתה נשואה לראש חברת התקליטים שלה, והתדמית שלה הייתה מבוקרת בקפידה. ב־1997 היא נפרדה ממנו, ו־Butterfly, שיצא בסתיו אותה שנה, היה האלבום שבו היא השתחררה: אישי יותר, נועז יותר, וקרוב הרבה יותר להיפ הופ ולרית׳ם אנד בלוז שהיא תמיד אהבה.''',
'''קארי עבדה כאן עם מפיקים וראפרים מעולם ההיפ הופ, ביניהם שון "פאפי" קומבס ומיסי אליוט (אלבום 839), אבל השאירה במרכז את הקול שלה, שעובר מלחישה רכה לצלילים גבוהים ומדהימים. Honey, שיר הפתיחה, הוא שיר קיצי, שמח וקליל, שנכנס ישר למקום הראשון במצעד האמריקאי. Butterfly, השיר שנתן לאלבום את שמו, הוא בלדה גדולה ומרגשת על שחרור ועל לתת למישהו שאוהבים לעוף. My All, עם גיטרה בסגנון לטיני, הוא שיר אהבה כמה ודרמטי, ו־The Roof הוא שיר לילי ונוסטלגי, שבנוי על קצב של שיר היפ הופ מוכר.''',
'''Butterfly נמכר במיליוני עותקים, ונחשב בעיני רבים, ובעיני קארי עצמה, לאחד האלבומים האישיים והחשובים שלה. הוא סימן את המעבר שלה מזמרת פופ מלוטשת לאמנית שמחברת בין פופ, סול והיפ הופ, כיוון שהשפיע על זמרות רבות שבאו אחריה.''',
'''שמעו את Butterfly, ושימו לב לשליטה המדהימה של קארי בקול, בעיקר בצלילים הגבוהים. ואחר כך עברו ל־Honey, כדי לשמוע את הצד הקליל והשמח שלה.''',
], [
('Honey', 'שיר קיצי, שמח וקליל, עם קצב היפ הופ וקול רך.'),
('Butterfly', 'בלדה גדולה ומרגשת על שחרור, עם קול שעולה לגבהים מדהימים.'),
('My All', 'שיר אהבה כמה ודרמטי, עם גיטרה בסגנון לטיני.'),
])

add(853, [
'''סופרגראס, שלושה צעירים מאוקספורד, הפכו לכוכבים כמעט בן לילה ב־1995 עם I Should Coco (אלבום 795) והשיר Alright, שהפך להמנון של קיץ בריטי שמח. אבל ההצלחה הזאת הייתה גם מלכודת: כולם ראו בהם להקה מצחיקה של ילדים שובבים. ב־In It for the Money, שיצא באביב 1997, הם הוכיחו שהם הרבה יותר מזה. האלבום בוגר, מגוון ושאפתני יותר, עם שירים אפלים ומורכבים לצד הרוקנרול השמח, והוא הגיע למקום השני במצעד הבריטי וזכה לשבחים רבים.''',
'''הצליל מחבר בין רוק של שנות השישים והשבעים, בסגנון הביטלס, הקינקס והרולינג סטונז, עם כלי נשיפה, אורגן, פסנתר וצלילים מוזרים של סינתיסייזרים ישנים. הזמר והגיטריסט גאז קומבס שר בקול חזק ומחוספס, והמתופף דני גופי מנגן באנרגיה מתפרצת. Richard III הוא שיר רוק רועש ופרוע, עם גיטרות מעוותות וצעקות. Late in the Day הוא שיר יפה ונוגה, עם גיטרה אקוסטית ומלודיה עצובה, ו־Sun Hits the Sky הוא שיר סוחף ושמשי, עם כלי נשיפה ואורגן, שמרגיש כמו בוקר של קיץ. השיר שנותן לאלבום את שמו פותח אותו בצורה מפתיעה, איטית ומאיימת.''',
'''In It for the Money נחשב בעיני רבים לאלבום הטוב ביותר של סופרגראס, האלבום שבו להקת הנערים הפכה ללהקה של מוזיקאים בוגרים. הלהקה המשיכה עוד כעשור, ונשארה אחת הלהקות האהובות של התקופה.''',
'''השוו את Richard III ל־Alright מ־I Should Coco (אלבום 795), כדי לשמוע כמה הלהקה גדלה בשנתיים. ושמעו את Sun Hits the Sky בבוקר שמשי.''',
], [
('Richard III', 'רוק רועש ופרוע, עם גיטרות מעוותות וצעקות מלאות אנרגיה.'),
('Late in the Day', 'שיר יפה ונוגה, עם גיטרה אקוסטית ומלודיה עצובה.'),
('Sun Hits the Sky', 'שיר סוחף ושמשי, עם כלי נשיפה ואורגן, כמו בוקר של קיץ.'),
])

add(854, [
'''בשנות התשעים בוב דילן, גדול כותבי השירים של הרוק, כבר היה אגדה, אבל רבים חשבו שימיו הגדולים מאחוריו. במשך כמה שנים הוא הוציא בעיקר אלבומים של שירי עם ישנים, ולא כתב שירים חדשים רבים. Time Out of Mind, שיצא בסתיו 1997, הפתיע את כולם: אלבום חדש, אפל ועמוק, שנחשב לאחד הטובים שלו מאז Blood on the Tracks (אלבום 341). זמן קצר לפני צאתו אושפז דילן עם מחלה קשה בלב, והשירים, שנכתבו לפני כן, נשמעו פתאום כמו מחשבות של אדם שמביט במוות.''',
'''את האלבום הפיק דניאל לנואה, מפיק קנדי שידוע בצליל עמוק, מהדהד וערפילי, והמוזיקה כאן נשמעת כמו בלוז ישן שמוקלט בתוך חלום: גיטרות רכות, אורגן, תופים איטיים והרבה הדהוד. הקול של דילן כבר זקן, צרוד ושבור, אבל דווקא זה מה שנותן לשירים את כוחם. Love Sick, שיר הפתיחה, הוא שיר איטי ואפל על אהבה שהפכה למחלה. Not Dark Yet הוא אחד השירים היפים שכתב, על אדם עייף שמרגיש שהחושך מתקרב, "עוד לא חשוך, אבל זה מגיע". Make You Feel My Love הוא שיר אהבה פשוט ועדין, שזמרים רבים הקליטו אחריו, ובהם אדל. Highlands, שסוגר את האלבום, נמשך יותר משש עשרה דקות.''',
'''Time Out of Mind זכה בגראמי לאלבום השנה, והחזיר את דילן למרכז הבמה. הוא פתח תקופה חדשה ופורייה בקריירה שלו, עם אלבומים מוערכים נוספים, ובהמשך גם פרס נובל לספרות.''',
'''שמעו את Not Dark Yet בשקט, בלילה, והקשיבו למילים. והשוו את דילן הזקן לדילן הצעיר של Highway 61 Revisited (אלבום 58): אותו כותב, שלושים ושתיים שנים אחר כך.''',
], [
('Love Sick', 'פתיחה איטית ואפלה, על אהבה שהפכה למחלה, עם אורגן מהדהד.'),
('Not Dark Yet', 'אחד השירים היפים שכתב, על אדם עייף שמרגיש שהחושך מתקרב.'),
('Make You Feel My Love', 'שיר אהבה פשוט ועדין, שזמרים רבים הקליטו אחריו.'),
])

add(855, [
'''רוני סייז הוא מפיק מבריסטול, העיר שבשנות התשעים נתנה לעולם את מאסיב אטאק (אלבום 703), פורטיסהד (אלבום 760) וטריקי (אלבום 788). הוא גדל בשכונה של מהגרים מהאיים הקריביים, התאהב בהיפ הופ ובג׳אנגל, והקים קבוצה של מפיקים, תקליטנים וזמרים בשם רפרזנט. New Forms, האלבום הראשון שלהם, יצא בקיץ 1997, ובאותה שנה זכה בפרס מרקורי, כשהוא עוקף את OK Computer של רדיוהד (אלבום 837). זה היה רגע גדול לדראם אנד בייס, שהגיע פתאום לקהל רחב בהרבה.''',
'''מה שמיוחד ב־New Forms הוא שהוא מחבר בין הקצבים האלקטרוניים המהירים של הדראם אנד בייס לבין נגינה חיה: קונטרבס אמיתי, כמו בג׳אז, תופים, גיטרה, ושירה וראפ. התוצאה נשמעת חמה, אורגנית וג׳אזית, אבל עדיין מהירה ועירונית. Brown Paper Bag, הקטע המפורסם, בנוי סביב קו קונטרבס ג׳אזי ומקפיץ, מעל תופים שבורים ומהירים. New Forms, עם הראפרית האמריקאית בהמדיה, הוא שיר רגוע וחכם. Heroes ו־Share the Fall, עם הזמרת אונלי, מחברים קול נשי רך עם קצב מהיר ובס עמוק, כמו סול שפוגש מועדון לילה.''',
'''New Forms הוכיח שהדראם אנד בייס יכול להיות מוזיקה של להקה ולא רק של תקליטנים, ורפרזנט הופיעו עם נגנים חיים על במות גדולות. האלבום נחשב עד היום לאחד מאבני הדרך של המוזיקה האלקטרונית הבריטית, לצד Timeless של גולדי (אלבום 805).''',
'''הקשיבו ל־Brown Paper Bag באוזניות, ושימו לב לקונטרבס שמנגן מעל התופים המהירים. והשוו ל־Logical Progression של LTJ בוקם (אלבום 828), צד רך יותר של אותו עולם.''',
], [
('Brown Paper Bag', 'קו קונטרבס ג׳אזי ומקפיץ, מעל תופים שבורים ומהירים.'),
('Heroes', 'קול נשי רך מעל קצב מהיר ובס עמוק, כמו סול במועדון לילה.'),
('Share the Fall', 'שיר חם ומלודי, עם שירה רכה וקצב שלא נעצר.'),
])

add(856, [
'''אליוט סמית׳ גדל בטקסס ובפורטלנד שבאורגון, ניגן בתחילת שנות התשעים בלהקת רוק רועשת, ובמקביל התחיל להקליט לבד, בבית, שירים שקטים ועצובים עם גיטרה אקוסטית. Either/Or, אלבום הסולו השלישי שלו, יצא בתחילת 1997 בחברת תקליטים קטנה, ושמו לקוח מספר של הפילוסוף הדני קירקגור. זמן קצר אחר כך שמע אותו הבמאי גאס ואן סנט, ושילב כמה משיריו בסרט Good Will Hunting. שיר שכתב במיוחד לסרט היה מועמד לפרס האוסקר, וסמית׳, ביישן ושקט, עמד בחליפה לבנה והופיע בטקס מול מיליוני צופים.''',
'''השירים של סמית׳ רכים, לוחשים ומלאי יופי עצוב. הוא שר בקול שקט מאוד, לעתים קרובות בשתי שכבות של אותו קול, כמו לחישה כפולה, עם גיטרה אקוסטית מדויקת ומלודיות שמזכירות את הביטלס. מדי פעם מצטרפים תופים, פסנתר ובס, אבל הכל נשאר אינטימי, כמו מישהו ששר לעצמו בחדר. Between the Bars הוא שיר ערש עצוב ויפה, על שתייה ועל הבטחות. Say Yes, שסוגר את האלבום, הוא שיר אהבה קטן, אופטימי ומתוק, נדיר אצלו. Angeles הוא שיר מרהיב עם גיטרה מהירה ועדינה, על לוס אנג׳לס ועל הפיתויים שלה.''',
'''Either/Or נחשב לאחד האלבומים היפים של שנות התשעים, ולאחד האהובים ביותר על כותבי שירים צעירים. סמית׳ התמודד כל חייו עם דיכאון והתמכרויות, ומת ב־2003, בגיל שלושים וארבע בלבד. השירים שלו נשארו, ועוד מרגשים דורות חדשים של מאזינים.''',
'''זה אלבום להאזנה בשקט, באוזניות, לבד, בשעות הלילה. התחילו ב־Between the Bars, והקשיבו לקול הכפול והלוחש. ואם אהבתם את Pink Moon של ניק דרייק (אלבום 261), תמצאו כאן נשמה דומה.''',
], [
('Between the Bars', 'שיר ערש עצוב ויפה, עם גיטרה אקוסטית וקול לוחש.'),
('Say Yes', 'שיר אהבה קטן, אופטימי ומתוק, נדיר אצלו.'),
('Angeles', 'גיטרה מהירה ועדינה, על לוס אנג׳לס ועל הפיתויים שלה.'),
])

add(857, [
'''הוורב הגיעו מוויגן שבצפון אנגליה, ובתחילת שנות התשעים היו להקה פסיכדלית ורועשת, עם גיטרות מרחפות והזמר הכריזמטי ריצ׳רד אשקרופט. אחרי A Northern Soul (אלבום 799) הם התפרקו בפעם הראשונה, אבל ב־1997 חזרו, ו־Urban Hymns, שיצא בסתיו אותה שנה, הפך לאחד האלבומים הנמכרים בתולדות בריטניה. הוא זכה בפרסי בריט לאלבום הטוב ביותר וללהקה הטובה ביותר, והפך את אשקרופט לאחד הקולות המזוהים של סוף שנות התשעים.''',
'''הצליל של Urban Hymns גדול ורחב: גיטרות מצלצלות, כלי מיתר, בלדות איטיות והמנונים שנועדו לשירה המונית, יחד עם קטעים פסיכדליים ורועשים מהתקופה הקודמת של הלהקה. Bitter Sweet Symphony, השיר המפורסם, בנוי סביב קטע כלי מיתר חוזר ובלתי נשכח, שנלקח מגרסה תזמורתית לשיר של הרולינג סטונז. הדגימה הזאת עוררה מאבק משפטי ארוך, ובמשך שנים נרשמו הזכויות על השיר בשמם של ג׳אגר וריצ׳רדס, עד שהוחזרו לאשקרופט רק עשרים ושתיים שנה אחר כך. The Drugs Don't Work, בלדה שקטה ועצובה על מוות ופרידה, הגיע למקום הראשון במצעד הבריטי. Lucky Man הוא שיר חם ומלא תקווה, עם גיטרות רחבות.''',
'''Urban Hymns היה שיא הצלחתם של הוורב, אבל גם הסוף: הלהקה התפרקה שוב זמן קצר אחר כך, ואשקרופט המשיך לקריירת סולו. הקליפ של Bitter Sweet Symphony, שבו אשקרופט הולך ברחוב ונתקל באנשים בלי לעצור, הפך לאחד הקליפים המפורסמים של העשור.''',
'''השוו את האלבום ל־A Northern Soul (אלבום 799), ושמעו איך הלהקה הפכה מפסיכדליה רועשת להמנונים. ושימו לב ל־Cast No Shadow של אואזיס (אלבום 804), שנואל גלאגר הקדיש לאשקרופט.''',
], [
('Bitter Sweet Symphony', 'כלי מיתר חוזרים ובלתי נשכחים, והמנון על חיים שלא משתנים.'),
("The Drugs Don't Work", 'בלדה שקטה ועצובה על מוות ופרידה, שהגיעה למקום הראשון.'),
('Lucky Man', 'שיר חם ומלא תקווה, עם גיטרות רחבות וכלי מיתר.'),
])

add(858, [
'''ג׳ייסון פירס, שקורא לעצמו ג׳יי ספייסמן, היה אחד המייסדים של ספייסמן 3 (אלבום 641), ואחר כך הקים את ספיריצ׳ואלייזד, להקה שהמשיכה את הרוק הפסיכדלי והמהפנט, כמו ב־Lazer Guided Melodies (אלבום 720). בזמן הכתיבה של האלבום השלישי שלו, הוא עבר פרידה קשה מהקלידנית של הלהקה, קייט ראדלי, שהתחתנה בסתר עם ריצ׳רד אשקרופט מהוורב (אלבום 857). Ladies and Gentlemen We Are Floating in Space, שיצא ב־1997, נולד מתוך שברון הלב הזה, והוא נחשב לאחד האלבומים הגדולים של העשור. מגזין המוזיקה הבריטי NME בחר בו לאלבום השנה, לפני OK Computer.''',
'''המוזיקה היא שילוב מרהיב של רוק פסיכדלי, גוספל, ג׳אז חופשי ובלוז, עם מקהלת גוספל, כלי נשיפה, כלי מיתר, גיטרות רועשות ורגעים של שקט מוחלט. פירס שר בקול שקט, עייף ושביר, על אהבה שאבדה, על בדידות ועל התמכרות. השיר שנותן לאלבום את שמו פותח אותו בעדינות, עם קולות שמתלכדים לאט. Come Together הוא שיר רוק אדיר ורועש, עם כלי נשיפה וגיטרות שמתפוצצות. Broken Heart הוא בלדה איטית ושבורה, עם כלי מיתר, אחד השירים העצובים שנכתבו. Cop Shoot Cop, שסוגר את האלבום, נמשך כשבע עשרה דקות, עם הפסנתרן האגדי דוקטור ג׳ון.''',
'''גם העטיפה של האלבום מפורסמת: היא עוצבה כמו קופסה של תרופת מרשם, עם הוראות שימוש והתרעות, ובמהדורה מיוחדת אפילו כמו לוח של כדורים. האלבום נשאר אחד היפים והמרגשים של סוף שנות התשעים.''',
'''זה אלבום שצריך לשמוע מההתחלה ועד הסוף, באוזניות ובווליום גבוה. ושמעו את Broken Heart לבד, בשקט. ואם אהבתם את Playing with Fire של ספייסמן 3 (אלבום 641), תשמעו כאן לאן הרעיון התפתח.''',
], [
('Come Together', 'רוק אדיר ורועש, עם כלי נשיפה וגיטרות שמתפוצצות.'),
('Broken Heart', 'בלדה איטית ושבורה עם כלי מיתר, אחד השירים העצובים שנכתבו.'),
('Ladies and Gentlemen We Are Floating in Space', 'פתיחה עדינה ומרחפת, עם קולות שמתלכדים לאט.'),
])

add(859, [
'''הדנדי וורהולז הם להקה מפורטלנד שבאורגון, שהקים בתחילת שנות התשעים הזמר והגיטריסט קורטני טיילור־טיילור. השם שלה הוא מחווה לאנדי וורהול, האמן שהיה הפטרון של הוולווט אנדרגראונד (אלבום 91), והמוזיקה שלה שואבת מאותו מקור: רוק פסיכדלי, מהפנט וקריר, עם גיטרות מעוותות, אורגן ושירה עייפה. ...The Dandy Warhols Come Down, שיצא ב־1997, היה האלבום השני שלהם, ובבריטניה הוא הפך להצלחה גדולה, עם כמה סינגלים במצעד, הרבה יותר מאשר בארצם.''',
'''האלבום עובר בין שירי פופ קליטים ושמחים לבין קטעים ארוכים, איטיים ומהפנטים, שנשמעים כמו טריפ פסיכדלי. יש בו גיטרות רועשות ומעוותות, אורגן חם של הקלידנית זיה מקייב, ותופים חוזרים בסגנון הקראוטרוק הגרמני. Not If You Were the Last Junkie on Earth, הלהיט הגדול, הוא שיר פופ קופצני ושמח, שמילותיו בעצם לועגות להתמכרות. Every Day Should Be a Holiday הוא שיר קליל ומתוק עם פזמון שמזמין לשיר, ו־Boys Better הוא שיר רוק מחוספס עם ריף גיטרה פשוט ומדבק. Cool as Kim Deal הוא מחווה קצרה לבסיסטית של הפיקסיז.''',
'''הדנדי וורהולז הפכו לאחת הלהקות המוכרות של רוק האינדי של סוף שנות התשעים. כמה שנים אחר כך שיר שלהם, Bohemian Like You, הופיע בפרסומת מצליחה והפך ללהיט עולמי, וסרט תיעודי, Dig!, תיאר את היריבות והחברות שלהם עם להקה אחרת מאותה סצנה.''',
'''אם אהבתם את The Velvet Underground & Nico (אלבום 91) או את ספייסמן 3 (אלבום 641), תשמעו כאן את ההשפעה. התחילו ב־Not If You Were the Last Junkie on Earth.''',
], [
('Not If You Were the Last Junkie on Earth', 'פופ קופצני ושמח, שמילותיו לועגות להתמכרות.'),
('Every Day Should Be a Holiday', 'שיר קליל ומתוק עם פזמון שמזמין לשיר.'),
('Boys Better', 'רוק מחוספס עם ריף גיטרה פשוט ומדבק.'),
])

add(860, [
'''במאי 1966 יצא בוב דילן לסיבוב הופעות בבריטניה עם להקת ההוקס, שנקראה מאוחר יותר דה בנד (אלבומים 127 ו־155). שנה קודם הוא התחיל לנגן בגיטרה חשמלית, וחלק גדול מקהל הפולק שאהב אותו ראה בזה בגידה. כל ערב היה בנוי משני חלקים: בחלק הראשון דילן לבד, עם גיטרה אקוסטית ומפוחית, ובחלק השני עם הלהקה, ברעש חשמלי. ההקלטה מההופעה במנצ׳סטר הופצה במשך שנים כתקליט פיראטי, בטעות בשם "הקונצרט ברויאל אלברט הול", והשם נשאר גם כשיצאה רשמית, ב־1998.''',
'''החלק האקוסטי שקט, מהפנט ויפה: דילן שר לבד את Visions of Johanna, Desolation Row ו־Mr. Tambourine Man, בקול מתוח ומרוכז, והקהל מקשיב בשקט מוחלט. החלק החשמלי הוא סיפור אחר לגמרי: הלהקה מנגנת בעוצמה עצומה, עם תופים רועשים, אורגן וגיטרות, והקהל מתחיל למחות, למחוא כפיים בקצב ולצעוק. ואז מגיע אחד הרגעים המפורסמים בתולדות הרוק: צופה צועק לדילן "יהודה!", כלומר בוגד. דילן עונה לו בשקט, פונה ללהקה, ומבקש לנגן חזק, והם פורצים לגרסה אדירה ורועשת של Like a Rolling Stone.''',
'''ההקלטה הזאת נחשבת לאחת מהקלטות ההופעה החשובות בתולדות הרוק, כי היא תופסת את הרגע שבו הרוק והפולק נפגשו והתנגשו, ואת אמן שעמד מול הקהל שלו ולא נכנע. הנגינה של ההוקס כאן היא מהטובות שנשמעו ברוק של שנות השישים.''',
'''שמעו קודם את Visions of Johanna האקוסטי, ואחר כך דלגו לסוף, ל־Like a Rolling Stone, והקשיבו לצעקה ולתשובה. והשוו לגרסאות באולפן ב־Highway 61 Revisited (אלבום 58) וב־Blonde on Blonde (אלבום 64).''',
], [
('Visions of Johanna', 'שיר ארוך ומהפנט, דילן לבד עם גיטרה ומפוחית, והקהל בשקט מוחלט.'),
('Like a Rolling Stone', 'אחרי הצעקה "יהודה!", גרסה אדירה ורועשת עם הלהקה.'),
('Desolation Row', 'מסע ארוך ופואטי, עם גיטרה אקוסטית ודמויות מוזרות.'),
])

add(861, [
'''מאנו צ׳או נולד בפריז להורים שברחו מספרד של פרנקו, וגדל בין שפות ותרבויות. בשנות השמונים והתשעים הוא הוביל את מאנו נגרה, להקה פרועה שחיברה פאנק, רוק ומוזיקה לטינית, ונדדה בכל העולם, כולל מסע ארוך ברכבת ישנה בקולומביה. כשהלהקה התפרקה, הוא יצא לבד למסעות באמריקה הלטינית ובאפריקה, עם גיטרה ומכשיר הקלטה נייד, והקליט שירים בחדרי מלון, בבתים ובדרכים. מהם נולד Clandestino, אלבום הסולו הראשון שלו, שיצא ב־1998.''',
'''המוזיקה פשוטה, חמה ומשוטטת: גיטרה אקוסטית, קצבים של רגאיי, סלסה ומוזיקה עממית, כלי נשיפה קטנים, ודגימות של קולות מתוך הרדיו, צפצופים וקולות של רחוב. צ׳או שר בספרדית, בצרפתית, באנגלית ובפורטוגזית, בקול רך ומעט מחוספס. השירים עוסקים במהגרים, בפליטים ובאנשים בלי ניירות, שחיים בצל, במאבקים פוליטיים ובאהבה. Clandestino, השיר שנתן לאלבום את שמו, הוא שיר שקט ונוגה על מהגר בלתי חוקי. Bongo Bong הוא שיר שמח ומקפיץ על מלך הבונגו, ו־Welcome to Tijuana הוא שיר קצבי ומצחיק על עיר הגבול בין מקסיקו לארצות הברית. כמה מלודיות חוזרות בשירים שונים, וכך האלבום מרגיש כמו מסע אחד.''',
'''Clandestino נמכר לאט בהתחלה, אבל בהמשך הפך להצלחה ענקית באירופה ובאמריקה הלטינית, במיליוני עותקים. הוא הפך את מאנו צ׳או לאחד הקולות של התנועה נגד הגלובליזציה, ולאמן אהוב בעשרות ארצות, למרות שכמעט לא שר באנגלית. השירים שלו נשמעים עד היום במסיבות, בטיולים ובהפגנות ברחבי העולם.''',
'''זה אלבום מושלם לנסיעה ארוכה, לטיול או לקיץ. שימו לב למלודיות שחוזרות משיר לשיר, ולקולות הרדיו שמחברים ביניהם. התחילו ב־Clandestino.''',
], [
('Clandestino', 'שיר שקט ונוגה על מהגר בלתי חוקי, עם גיטרה אקוסטית.'),
('Bongo Bong', 'שיר שמח ומקפיץ על מלך הבונגו, עם קצב שנדבק.'),
('Welcome to Tijuana', 'שיר קצבי ומצחיק על עיר הגבול בין מקסיקו לארצות הברית.'),
])

add(862, [
'''וודי גאת׳רי, זמר העם האמריקאי הגדול של שנות השלושים והארבעים, השאיר אחריו אלפי שירים שכתב, אבל מעולם לא הקליט, ורבים מהם בלי מנגינה בכלל. באמצע שנות התשעים פנתה בתו, נורה גאת׳רי, לזמר הבריטי בילי בראג (אלבום 570), שידוע בשירי מחאה ובשירי אהבה, וביקשה ממנו לכתוב מוזיקה למילים של אביה. בראג הזמין להצטרף את ווילקו (אלבום 819), הלהקה האמריקאית של ג׳ף טווידי, ו־Mermaid Avenue, שיצא ב־1998, הוא התוצאה. השם לקוח מהרחוב בקוני איילנד שבו גר גאת׳רי עם משפחתו.''',
'''הכיף הגדול באלבום הוא לגלות כמה גאת׳רי היה מגוון: לצד שירי מחאה פוליטיים יש כאן שירי אהבה, שירים מצחיקים, שירים על ילדים ושירים על כוכבי קולנוע. בראג וטווידי מתחלפים בשירה, כל אחד בסגנון שלו: בראג עם מבטא בריטי חזק וגיטרה פשוטה, טווידי עם קול רך וקאנטרי רוק חם. California Stars, שטווידי שר, הוא שיר נינוח ויפה על חלום לישון תחת הכוכבים של קליפורניה. Ingrid Bergman הוא שיר אהבה קטן ומצחיק לשחקנית השוודית, שבראג שר רק עם גיטרה. Way Over Yonder in the Minor Key הוא שיר מתוק על אהבה צעירה, והזמרת נטלי מרצ׳נט מצטרפת ב־Birds and Ships.''',
'''Mermaid Avenue היה מועמד לגראמי, הביא את גאת׳רי לדור חדש, ובעקבות ההצלחה יצאו עוד שני אלבומים עם שירים נוספים מהארכיון. הוא הוכיח שהמילים של גאת׳רי עדיין חיות ורעננות, כמעט חמישים שנה אחרי שנכתבו.''',
'''שמעו את California Stars בערב נעים, ואת Ingrid Bergman כדי לחייך. ואם אהבתם את Being There של ווילקו (אלבום 819), תשמעו כאן אותה להקה בצד רגוע ועממי יותר.''',
], [
('California Stars', 'שיר נינוח ויפה על חלום לישון תחת הכוכבים, בקולו של טווידי.'),
('Ingrid Bergman', 'שיר אהבה קטן ומצחיק לשחקנית השוודית, רק עם גיטרה.'),
('Way Over Yonder in the Minor Key', 'שיר מתוק על אהבה צעירה, בקולו של בילי בראג.'),
])

add(863, [
'''טורבונגרו היא להקה מאוסלו שבנורווגיה, שהתחילה בסוף שנות השמונים כלהקת פאנק רועשת ומתגרה, ובמשך השנים פיתחה דימוי מוזר ומצחיק: חליפות ג׳ינס, כובעי מלחים, איפור כבד, והומור גס וקיצוני ששיחק בדימויים של גבריות. הם קראו לסגנון שלהם "דת׳ פאנק". Apocalypse Dudes, שיצא ב־1998, היה האלבום שבו הם מצאו את הצליל המושלם שלהם, בעיקר בזכות גיטריסט חדש, יורובוי, שהביא סולואים מבריקים של רוק כבד מהשבעים.''',
'''המוזיקה מחברת את האנרגיה המהירה והגסה של הפאנק עם הגיטרות הגדולות והסולואים של הרוק הכבד של שנות השבעים, בסגנון של הסטוג׳ז (אלבומים 171 ו־297), קיס ואליס קופר. הזמר, האנק פון הלווטה, שר בקול מחוספס ומלא כריזמה, והשירים קצרים, מהירים ומלאים בפזמונים שאפשר לצעוק בהופעה. המילים הן בדרך כלל בדיחות גסות ופרועות, חלקן בוטות מאוד. The Age of Pamparius, שפותח את האלבום, הוא שיר רוק אדיר עם ריף גיטרה מטורף. Back to Dungaree High הוא שיר מהיר ושמח על "תיכון הג׳ינס", ו־Are You Ready (For Some Darkness), שסוגר את האלבום, הוא המנון כבד ודרמטי.''',
'''זמן קצר אחרי צאת האלבום הלהקה התפרקה, אבל בשנים שאחר כך הוא הפך לאגדה, ואוהדים בכל העולם הקימו מועדוני מעריצים בשם "טורבוג׳וגנד", עם מעילי ג׳ינס תואמים. הלהקה חזרה בתחילת שנות האלפיים, והופיעה מול קהלים גדולים בהרבה מבעבר.''',
'''שמעו את The Age of Pamparius בקול רם, ושימו לב לסולו הגיטרה. ואם אהבתם את Raw Power של איגי והסטוג׳ז (אלבום 297), תמצאו כאן את הנכדים הנורווגיים שלו.''',
], [
('The Age of Pamparius', 'שיר רוק אדיר עם ריף גיטרה מטורף וסולו מבריק.'),
('Back to Dungaree High', 'שיר מהיר ושמח על "תיכון הג׳ינס", עם פזמון לצעוק.'),
('Are You Ready (For Some Darkness)', 'המנון כבד ודרמטי שסוגר את האלבום.'),
])

add(864, [
'''אחרי Better Living Through Chemistry (אלבום 809), נורמן קוק, פטבוי סלים, כבר היה תקליטן מוכר בבריטניה. אבל You've Come a Long Way, Baby, שיצא בסתיו 1998, הפך אותו לכוכב עולמי. האלבום הגיע למקום הראשון במצעד הבריטי, נמכר במיליוני עותקים בכל העולם, וכמה מהשירים שלו נשמעו בכל מקום: בפרסומות, בסרטים, במשחקי וידאו ובאירועי ספורט. השם לקוח מסיסמה של פרסומת סיגריות ישנה, ועל העטיפה יש תמונה של בחור שמנמן בחולצה עם כיתוב יהיר ומצחיק.''',
'''כמו באלבום הקודם, הכל בנוי מדגימות: קטעים קצרים מתקליטים ישנים של פאנק, סול, רוק והיפ הופ, שחוזרים שוב ושוב, נבנים ומתפוצצים. אבל כאן הכל חד, שמח ומסחרי יותר. The Rockafeller Skank, עם המשפט החוזר על "האח של הפאנק והסול" וגיטרת סרף מהירה, הוא אחד משירי הריקוד הידועים של העשור. Praise You, שמבוסס על שיר סול נשכח, מתחיל בפסנתר וקול נשי ונבנה למסיבה שמחה. הקליפ שלו, שבו קבוצה של רקדנים חובבים רוקדת מול קולנוע ברחוב, הפך למפורסם. Right Here, Right Now הוא קטע איטי ודרמטי, עם גיטרה כבדה וקול שחוזר על שם השיר.''',
'''You've Come a Long Way, Baby הוא שיא של הביג ביט, הסגנון השמח והרועש של סוף שנות התשעים. פטבוי סלים הפך לאחד התקליטנים המפורסמים בעולם, וכמה שנים אחר כך הופיע על חוף הים בברייטון, עירו, מול קהל עצום.''',
'''השוו את האלבום ל־Better Living Through Chemistry (אלבום 809), ושמעו איך הנוסחה השתכללה. ושימו לב איך Praise You נבנה מכמה צלילים פשוטים לשמחה גדולה.''',
], [
('The Rockafeller Skank', 'משפט חוזר וגיטרת סרף מהירה, אחד משירי הריקוד הידועים של העשור.'),
('Praise You', 'מפסנתר וקול נשי למסיבה שמחה, עם קליפ מפורסם של רקדנים חובבים.'),
('Right Here, Right Now', 'קטע איטי ודרמטי, עם גיטרה כבדה וקול שחוזר על שם השיר.'),
])

add(865, [
'''דייוויד גריי נולד במנצ׳סטר וגדל בוויילס, ובשנות התשעים הוציא שלושה אלבומים של שירי פולק רוק כנים ורגישים, שזכו לשבחים של מבקרים אבל כמעט לא נמכרו. חברת התקליטים שלו ויתרה עליו, ולכן את האלבום הרביעי, White Ladder, הוא הקליט בדירה שלו בלונדון, עם תקציב זעום ושני חברים, והוציא אותו ב־1998 בחברה קטנה משלו. ואז קרה משהו מפתיע: באירלנד האלבום התחיל להימכר, בזכות הפה לאוזן ותחנות רדיו, והפך לאחד הנמכרים בתולדות המדינה. משם ההצלחה התפשטה לבריטניה ולאמריקה.''',
'''הצליל של White Ladder פשוט וחם: פסנתר, גיטרה אקוסטית, קצבים אלקטרוניים עדינים שהוקלטו בבית, וקולו המחוספס והרגשני של גריי, שמזכיר מעט את ואן מוריסון. השירים עוסקים באהבה, בגעגועים ובחיים בעיר. Babylon, הלהיט הגדול, הוא שיר על ערב שישי בעיר הגדולה ועל ההבנה המאוחרת שאוהבים מישהו, עם גיטרה אקוסטית וקצב מתגלגל. Please Forgive Me הוא שיר אהבה מרגש עם קצב אלקטרוני רך, ו־This Year's Love הוא בלדה שקטה ונוגעת ללב עם פסנתר, על הפחד והתקווה של אהבה חדשה. האלבום נסגר בגרסה ארוכה ושקטה לשיר של סופט סל.''',
'''White Ladder הוא סיפור הצלחה נדיר: אלבום ביתי וזול, שהגיע למקום הראשון בבריטניה כמעט שנתיים אחרי שיצא, ונמכר במיליוני עותקים. הוא הראה שאפשר להצליח גם בלי חברת תקליטים גדולה, הרבה לפני שהאינטרנט הפך את זה לרגיל.''',
'''זה אלבום טוב לערב שקט בבית. התחילו ב־Babylon, ושימו לב לשילוב בין הגיטרה האקוסטית לקצב האלקטרוני העדין, שהיה חדש וטבעי באותה מידה.''',
], [
('Babylon', 'שיר על לילה בעיר והבנה מאוחרת של אהבה, עם גיטרה וקצב מתגלגל.'),
('Please Forgive Me', 'שיר אהבה מרגש עם קצב אלקטרוני רך וקול מחוספס.'),
("This Year's Love", 'בלדה שקטה עם פסנתר, על הפחד והתקווה של אהבה חדשה.'),
])

add(866, [
'''לוסינדה וויליאמס נולדה בלואיזיאנה וגדלה בערים שונות בדרום ארצות הברית, בתו של משורר, והתחילה לשיר שירי פולק וקאנטרי בבתי קפה עוד בשנות השבעים. במשך שנים היא נחשבה ל"כותבת של כותבים": זמרים אחרים הצליחו עם השירים שלה, והיא עצמה נשארה כמעט עלומה. Car Wheels on a Gravel Road יצא ב־1998, אחרי כשש שנים של עבודה, הקלטות חוזרות, החלפת מפיקים ופרפקציוניזם עקשני. כשהוא סוף סוף יצא, הוא זכה בגראמי, ומבקרים רבים בחרו בו לאלבום הטוב של השנה.''',
'''המוזיקה מחברת קאנטרי, בלוז, פולק ורוק, עם גיטרות חשמליות ואקוסטיות, אקורדיון ותופים, וצליל חם ומחוספס של להקה שמנגנת יחד בחדר. הקול של וויליאמס עייף, מתמשך ומלא מבטא דרומי, כמו מישהי שמספרת סיפור באמצע הלילה. השירים מלאים בשמות של מקומות בדרום, בכבישים, בעיירות קטנות ובזיכרונות. Right in Time, שפותח את האלבום, הוא שיר אהבה חושני ונינוח, עם גיטרה מתגלגלת. Car Wheels on a Gravel Road, השיר שנתן לאלבום את שמו, מספר על זיכרון ילדות: ילדה במושב האחורי של מכונית, נוסעת בכבישי עפר. Drunken Angel הוא שיר עצוב ויפה לזכרו של מוזיקאי חבר, שחי ומת בשוליים.''',
'''Car Wheels on a Gravel Road נחשב לאחד מאבני היסוד של האמריקנה, הסגנון שמחבר את המוזיקה העממית של אמריקה הכפרית עם כתיבה אישית ואיכותית. הוא הפך את וויליאמס, בגיל ארבעים וחמש, לכוכבת, והיא המשיכה להוציא אלבומים מוערכים עוד שנים רבות.''',
'''שמעו את האלבום בנסיעה, רצוי על כביש פתוח. ואם אהבתם את Pieces of the Sky של אמילו האריס (אלבום 335) או את Guitar Town של סטיב ארל (אלבום 580), שגם עזר להפיק את האלבום הזה, תרגישו כאן בבית.''',
], [
('Right in Time', 'שיר אהבה חושני ונינוח, עם גיטרה מתגלגלת וקול עייף.'),
('Car Wheels on a Gravel Road', 'זיכרון ילדות מהמושב האחורי של מכונית בכבישי עפר.'),
('Drunken Angel', 'שיר עצוב ויפה לזכרו של מוזיקאי חבר, שחי ומת בשוליים.'),
])

add(867, [
'''אחרי ההצלחה הענקית של Different Class (אלבום 801), ג׳רוויס קוקר ופאלפ הפכו לכוכבים, והתהילה הגיעה עם מחיר. קוקר, שחלם כל חייו להיות מפורסם, גילה שהחלום מרגיש ריק ומפחיד, והגיטריסט ראסל סניור עזב את הלהקה. This Is Hardcore, שיצא באביב 1998, הוא התשובה של קוקר להצלחה: אלבום אפל, איטי, עייף ומלא חרדה, על תהילה, על הזדקנות, על פחד ועל הצד המלוכלך של החיים. הוא הגיע למקום הראשון במצעד הבריטי, אבל רבים מהמעריצים שציפו לעוד Common People הופתעו.''',
'''המוזיקה עשירה ודרמטית יותר מבעבר, עם כלי מיתר, פסנתר, עוגב, צלילים קולנועיים ותזמורים גדולים, ולצידם גיטרות רועשות. קוקר שר בקול עמוק, מפתה ועייף, ולעתים קרובות לוחש ומדבר. The Fear, שפותח את האלבום, הוא שיר אימה של ממש, עם צלילים מוזרים ופזמון על הפחד שהפך לחבר הכי טוב. Help the Aged הוא שיר חם ומצחיק על הזדקנות, שקורא לצעירים לא לשכוח את הזקנים, כי גם הם יגיעו לשם. This Is Hardcore, השיר שנתן לאלבום את שמו, הוא קטע איטי, אפל וקולנועי, עם פסנתר וכלי מיתר, שמשתמש בעולם הסרטים למבוגרים כמשל לתעשיית התהילה. Dishes הוא שיר שקט ומצחיק על חיים רגילים, עם שורה מפורסמת שבה קוקר אומר שהוא לא ישו, למרות שיש להם אותן ראשי תיבות.''',
'''This Is Hardcore נחשב היום בעיני רבים לאלבום הטוב והאמיץ ביותר של פאלפ, אלבום שמביט מאחורי הקלעים של הבריטפופ.''',
'''השוו את Help the Aged ל־Common People מ־Different Class (אלבום 801): אותו קוקר, אבל שלוש שנים מבוגר ועייף יותר.''',
], [
('The Fear', 'שיר אימה של ממש, עם צלילים מוזרים ופזמון על פחד.'),
('Help the Aged', 'שיר חם ומצחיק על הזדקנות, שקורא לא לשכוח את הזקנים.'),
('This Is Hardcore', 'קטע איטי, אפל וקולנועי, עם פסנתר וכלי מיתר.'),
])

add(868, [
'''מדונה הייתה כבר כוכבת הפופ הגדולה בעולם במשך יותר מעשור, עם אלבומים כמו Like a Prayer (אלבום 639), כשבאמצע שנות התשעים חייה השתנו: היא נולדה לה בת ראשונה, והיא התחילה להתעניין ביוגה, במדיטציה, בקבלה ובפילוסופיה של המזרח. Ray of Light, שיצא בתחילת 1998, משקף את השינוי הזה. הוא רוחני, שקט ומהורהר יותר מכל מה שעשתה קודם, וגם חדשני מאוד מבחינה מוזיקלית. רבים רואים בו את האלבום הטוב ביותר שלה.''',
'''את המוזיקה הפיק יחד איתה המפיק הבריטי ויליאם אורביט, שהביא צלילים מעולם המוזיקה האלקטרונית של לונדון: טכנו, טריפ הופ, אמביינט וצלילים מרחפים, עם גיטרות אקוסטיות וכלי מיתר. הקול של מדונה נשמע כאן בוגר ועמוק יותר, אחרי שלמדה פיתוח קול. Frozen הוא שיר איטי, אפל ודרמטי, עם כלי מיתר וקצב אלקטרוני, על אדם שליבו קפוא. Ray of Light, השיר שנתן לאלבום את שמו, הוא שיר טכנו מהיר, שמח ומלא אור, על תחושה של חופש. The Power of Good-Bye היא בלדה עצובה ויפה על פרידה. יש גם שיר שמושר כולו בסנסקריט, השפה העתיקה של הודו.''',
'''Ray of Light זכה בכמה פרסי גראמי, נמכר ביותר מחמישה עשר מיליון עותקים, וחידש את הקריירה של מדונה, שהראתה שוב שהיא יודעת לזהות כיוון חדש לפני כולם. הוא הביא את הצליל האלקטרוני הבריטי לפופ העולמי, והשפיע על זמרות רבות.''',
'''השוו את Ray of Light ל־Like a Prayer (אלבום 639), ושמעו כמה מדונה השתנתה בתשע שנים. ושימו לב לכלי המיתר ב־Frozen, שמתחברים לקצב האלקטרוני.''',
], [
('Frozen', 'שיר איטי ודרמטי עם כלי מיתר וקצב אלקטרוני, על לב קפוא.'),
('Ray of Light', 'טכנו מהיר, שמח ומלא אור, על תחושה של חופש.'),
('The Power of Good-Bye', 'בלדה עצובה ויפה על פרידה, עם גיטרה וכלי מיתר.'),
])

add(869, [
'''לורין היל הייתה הקול והלב של הפוג׳יז (אלבום 833), ואחרי ההצלחה העצומה של The Score היא הוציאה ב־1998 את אלבום הסולו היחיד שלה באולפן, The Miseducation of Lauryn Hill. הוא נכתב בתקופה של שינויים גדולים בחייה: סוף הקשר עם וויקלף ז׳אן, חבר הלהקה, ולידה של בן ראשון. האלבום זכה בחמישה פרסי גראמי, ביניהם אלבום השנה, וזה היה אלבום ההיפ הופ הראשון שזכה בפרס הזה. השם רומז לספר חשוב על החינוך של אפרו־אמריקאים.''',
'''המוזיקה מחברת היפ הופ, סול, רגאיי וגוספל, עם נגנים חיים, כלי מיתר, מקהלה ותופים חמים, והיל עוברת בטבעיות בין ראפ חד ומהיר לשירה נפלאה. בין השירים יש קטעים קצרים שבהם מורה מדבר עם ילדים בכיתה על אהבה, וכך האלבום מרגיש כמו שיעור. Doo Wop (That Thing), הלהיט הגדול, הוא שיר שמח ומלא אנרגיה, עם כלי נשיפה, שמזהיר בחורות ובחורים מפני מערכות יחסים ריקות. הוא נכנס ישר למקום הראשון במצעד האמריקאי. Ex-Factor היא בלדת סול כואבת על אהבה שלא עובדת, ו־To Zion הוא שיר אישי ומרגש לבנה, עם הגיטרה של קרלוס סנטנה.''',
'''The Miseducation of Lauryn Hill נחשב לאחד האלבומים החשובים של שנות התשעים, ולאחד המשפיעים ביותר על זמרות וראפריות שבאו אחריו. היל עצמה כמעט לא הוציאה מוזיקה חדשה באולפן מאז, וזה רק הגדיל את האגדה.''',
'''שמעו את To Zion, ושימו לב לגיטרה של סנטנה. והשוו את Doo Wop (That Thing) ל־Killing Me Softly מ־The Score (אלבום 833), כדי לשמוע איך היל התפתחה לבד.''',
], [
('Doo Wop (That Thing)', 'שיר שמח ומלא אנרגיה עם כלי נשיפה, אזהרה מפני מערכות יחסים ריקות.'),
('Ex-Factor', 'בלדת סול כואבת על אהבה שלא עובדת, עם קול נפלא.'),
('To Zion', 'שיר אישי ומרגש לבנה, עם הגיטרה של קרלוס סנטנה.'),
])

add(870, [
'''הול, הלהקה של קורטני לאב, הוציאה ב־1994 את Live Through This (אלבום 774), אלבום רועש וכועס שיצא ימים ספורים אחרי מותו של בעלה, קורט קוביין מנירוונה. ארבע שנים אחר כך, ב־1998, יצא Celebrity Skin, וכולם הופתעו: במקום הפאנק המחוספס, זה אלבום פופ רוק מבריק, שמשי וקליפורני, עם גיטרות נקיות, הרמוניות ומלודיות גדולות. בילי קורגן מהסמאשינג פאמפקינס עזר לכתוב כמה מהשירים, ולאב עצמה תיארה את האלבום כאלבום על קליפורניה, על הוליווד ועל המחיר של תהילה.''',
'''הצליל מושפע מרוק של שנות השבעים, בסגנון פליטווד מק, עם גיטרות מצלצלות, כלי מיתר ומלודיות שמזמינות לשיר, אבל עם הכעס והציניות של לאב, שנשמעים מתחת לפני השטח. Celebrity Skin, שיר הפתיחה, הוא רוק סוחף ונמרץ, עם ריף גיטרה גדול ומילים חדות על עולם הסלבריטאים. Malibu הוא שיר שמשי ועצוב על בריחה לחוף, ורבים רואים בו שיר על קוביין. Awful הוא שיר פופ פאנק קליל וקופצני, על בנות צעירות ועל עולם שמנסה לשלוט בהן. האלבום כולו נשמע כמו נסיעה במכונית פתוחה לאורך החוף, אבל עם עננים כהים באופק.''',
'''Celebrity Skin היה מועמד לכמה פרסי גראמי, ונחשב לאלבום המלוטש והנגיש ביותר של הול. הוא הראה שקורטני לאב, שרבים זכרו בעיקר כדמות שנויה במחלוקת, היא כותבת שירים מוכשרת. במבט לאחור, רבים רואים בו את האלבום המגובש והבשל ביותר של הלהקה, ומבקרים שזלזלו בו בזמנו שינו את דעתם.''',
'''השוו את Celebrity Skin ל־Live Through This (אלבום 774), ושמעו איך אותה להקה עברה מצעקה לפופ רוק שמשי. התחילו בשיר הפתיחה, בקול רם.''',
], [
('Celebrity Skin', 'רוק סוחף ונמרץ, עם ריף גיטרה גדול ומילים חדות על סלבריטאים.'),
('Malibu', 'שיר שמשי ועצוב על בריחה לחוף, עם גיטרות מצלצלות.'),
('Awful', 'פופ פאנק קליל וקופצני, על בנות צעירות ועולם שמנסה לשלוט בהן.'),
])

add(871, [
'''מרקורי רב היא להקה מבאפלו שבמדינת ניו יורק, שהתחילה בסוף שנות השמונים כלהקת רוק פסיכדלית רועשת ומבולגנת, עם המון פידבק וניסויים. הזמר ג׳ונתן דונהיו ניגן בתחילת דרכו גם עם הפליימינג ליפס (אלבום 891). אחרי כמה אלבומים שזכו לשבחים אבל נכשלו מסחרית, הלהקה כמעט התפרקה. היא הסתגרה באזור הכפרי של רכס הקטסקילס, באזור שבו חיו והקליטו פעם חברי דה בנד, ושם, בשקט, נולד Deserter's Songs, שיצא ב־1998 והפך להצלחה הגדולה שלה. מגזין NME בחר בו לאלבום השנה.''',
'''במקום הרעש והפידבק, יש כאן מוזיקה עדינה, חלומית וקסומה, כמו פסקול לסרט ישן או לאגדה: כלי מיתר, חליל, קלרינט, פסנתר, פעמונים, ומסור מוזיקלי שמייבב בצליל מרחף. הקול של דונהיו גבוה, שביר ופגיע, כמעט כמו של ילד. שניים מחברי דה בנד, לבון הלם וגארת׳ הדסון, מנגנים כאורחים. Holes, שפותח את האלבום, הוא שיר איטי ויפה על זמן, על חורים ועל מה שמשאירים מאחור. Opus 40, על שם פסל אבן ענק ביער בקטסקילס, הוא שיר חם ונוסטלגי עם מלודיה מרגשת. Goddess on a Hiway הוא שיר פופ קליל ושמח, עם גיטרה ופזמון מתוק.''',
'''Deserter's Songs נחשב לאחד האלבומים היפים של סוף שנות התשעים, והשפיע על להקות רבות שחיפשו צליל עשיר, תזמורתי וחלומי. הוא הוכיח שגם להקה שכבר כמעט ויתרה יכולה למצוא קול חדש לגמרי.''',
'''זה אלבום לשעות הלילה, באוזניות, כמו לסיפור. התחילו ב־Holes, והקשיבו למסור המוזיקלי. והשוו ל־The Soft Bulletin של הפליימינג ליפס (אלבום 891), שהופק בידי אותו מפיק, דייב פרידמן.''',
], [
('Holes', 'שיר איטי ויפה על זמן ועל מה שמשאירים מאחור, עם כלי מיתר.'),
('Opus 40', 'שיר חם ונוסטלגי עם מלודיה מרגשת, על פסל אבן ביער.'),
('Goddess on a Hiway', 'פופ קליל ושמח, עם גיטרה ופזמון מתוק.'),
])

add(872, [
'''סיסטם אוף א דאון הם ארבעה מוזיקאים מלוס אנג׳לס, כולם ממוצא ארמני, צאצאים של ניצולי רצח העם הארמני. הם הקימו את הלהקה באמצע שנות התשעים, ומשכו תשומת לב בזכות הופעות פרועות ומוזיקה שלא דמתה לשום דבר אחר. המפיק המפורסם ריק רובין החתים אותם, ואלבום הבכורה שלהם, שנקרא פשוט System of a Down, יצא ב־1998. הוא לא הפך מיד ללהיט, אבל בזכות הופעות רבות לצד להקות מטאל גדולות, צבר קהל נאמן, והכין את הקרקע להצלחה העצומה של האלבום הבא.''',
'''המוזיקה מחברת מטאל כבד, מהיר וכאוטי, עם פאנק, מלודיות ארמניות ומזרח תיכוניות, והומור מטורף. השירים מחליפים כיוון כל כמה שניות: ריף כבד, ואז שירה עדינה, ואז צעקה, ואז קטע מצחיק כמעט כמו קרקס. הזמר, סרג׳ טנקיאן, הוא בעל קול גמיש ומדהים, שעובר מלחישה לשירה אופראית ולצעקה. המילים עוסקות בפוליטיקה, במלחמה, בתקשורת ובצדק. Sugar הוא השיר המוכר, עם ריף מקפיץ ושירה מטורפת. P.L.U.C.K., שסוגר את האלבום, הוא שיר זועם על רצח העם הארמני ועל ההכחשה שלו. Spiders הוא שיר איטי, אפל ומהפנט, שמראה צד אחר של הלהקה.''',
'''סיסטם אוף א דאון הפכו לאחת הלהקות החשובות של המטאל בתחילת שנות האלפיים, והביאו לקהל עולמי גם את ההיסטוריה של העם הארמני. האלבום הראשון מראה אותם בשיא הפראות והמקוריות שלהם.''',
'''שמעו את Sugar בקול רם, ושימו לב לכמה פעמים השיר מחליף כיוון. ואם אהבתם את Roots של ספולטורה (אלבום 820), תמצאו כאן עוד להקה שמחברת מטאל עם השורשים שלה.''',
], [
('Sugar', 'ריף מקפיץ ושירה מטורפת, שיר שמחליף כיוון כל כמה שניות.'),
('P.L.U.C.K.', 'שיר זועם על רצח העם הארמני ועל ההכחשה שלו.'),
('Spiders', 'שיר איטי, אפל ומהפנט, צד אחר ושקט של הלהקה.'),
])

add(873, [
'''ג׳וש הום התחיל את דרכו כנער בקייוס, להקה מהמדבר של דרום קליפורניה, שניגנה מסיבות במדבר עם גנרטורים, והמציאה סגנון כבד ואיטי שנקרא "סטונר רוק" או "רוק מדבר". כשקייוס התפרקה, הום רצה משהו אחר: רוק כבד, אבל גם מקפיץ, חוזר ומהפנט, כמו מכונה, משהו שגם בנות ירצו לרקוד אליו, כמו שהוא עצמו אמר. Queens of the Stone Age, אלבום הבכורה של הלהקה החדשה, יצא ב־1998. הום ניגן בעצמו כמעט את כל הכלים, חוץ מהתופים.''',
'''המוזיקה בנויה על ריפים פשוטים וחוזרים, שחוזרים שוב ושוב עד שהם הופכים למהפנטים, עם גיטרות עבות ונמוכות, תופים יבשים וחזקים, וקול רך ומפתה של הום, שמנוגד לכובד של המוזיקה. הוא קרא לזה "רובוט רוק". Regular John, שפותח את האלבום, בנוי על ריף אחד שחוזר ומתעצם, כמו נסיעה במדבר. Avon הוא שיר מקפיץ וכבד עם פזמון קליט. If Only הוא שיר רוק חם וקצבי, עם מלודיה מתוקה מעל גיטרות כבדות. יש כאן גם קטעים כליים קצרים ומוזרים, שמזכירים את הג׳אמים במדבר.''',
'''האלבום הראשון לא הפך ללהיט גדול, אבל הוא הניח את היסודות ללהקה שהפכה לאחת להקות הרוק החשובות של שנות האלפיים. כמה שנים אחר כך, עם אלבומים כמו Songs for the Deaf, הם כבשו קהל עצום, והום הפך לאחד הגיטריסטים והמפיקים המוערכים ברוק.''',
'''שמעו את Regular John בקול רם, ושימו לב איך ריף אחד יכול להחזיק שיר שלם. ואם אהבתם את Black Sabbath (אלבום 178), תשמעו כאן את הנכדים של הצליל הכבד שלהם.''',
], [
('Regular John', 'ריף אחד שחוזר ומתעצם, כמו נסיעה ארוכה במדבר.'),
('Avon', 'שיר מקפיץ וכבד, עם פזמון קליט וגיטרות עבות.'),
('If Only', 'רוק חם וקצבי, עם מלודיה מתוקה מעל גיטרות כבדות.'),
])

add(874, [
'''אייר הם שני צרפתים מוורסאי, ניקולא גודן וז׳אן־בנואה דנקל, שלמדו אדריכלות ומתמטיקה לפני שהחליטו להקדיש את עצמם למוזיקה. הם אהבו סינתיסייזרים ישנים, פסקולים של סרטים צרפתיים משנות השישים והשבעים, את סרז׳ גינסבורג (אלבום 225) ואת המוזיקה הרכה של ברט בכרך. Moon Safari, אלבום הבכורה שלהם, יצא בתחילת 1998, והפך להצלחה בינלאומית גדולה, לצד דאפט פאנק (אלבום 850), כחלק מהגל של המוזיקה האלקטרונית הצרפתית שכבשה את העולם.''',
'''אבל בניגוד לדאפט פאנק, המוזיקה של אייר רכה, איטית וחלומית, כמו טיול רגוע בחלל: סינתיסייזרים ישנים וחמים, פסנתר חשמלי, גיטרה אקוסטית, בס עגול, כלי מיתר, וקולות מעובדים במכשיר שהופך אותם לרובוטיים. La femme d'argent, שפותח את האלבום, הוא קטע כלי נינוח עם בס עגול ושמשי. Sexy Boy, הלהיט הגדול, הוא שיר מוזר ומפתה עם קול רובוטי ופזמון שנדבק. All I Need, עם הזמרת האמריקאית בת׳ הירש, הוא שיר אהבה עדין ושקט, ו־Kelly Watch the Stars הוא קטע שמח וקופצני, עם קול מעובד וסינתיסייזר מתוק.''',
'''Moon Safari הפך לאחד מאלבומי הרגיעה האהובים של סוף שנות התשעים, ונשמע מאז בבתי קפה, בפרסומות ובסרטים. הוא השפיע על מוזיקאים רבים שחיפשו צליל רך, חם ונוסטלגי, ונשאר עד היום אחד האלבומים הנעימים להאזנה מסוף המאה. הצליל הרך שלהם הפך לסימן ההיכר של מה שנקרא אז "צ׳יל אאוט", מוזיקה להירגע אחרי לילה ארוך.''',
'''זה אלבום לבוקר של שבת או לערב רגוע. התחילו ב־La femme d'argent, ותנו לבס להוביל אתכם. והשוו את האווירה ל־Histoire de Melody Nelson של גינסבורג (אלבום 225).''',
], [
("La femme d'argent", 'קטע כלי נינוח עם בס עגול ושמשי, פתיחה חלומית.'),
('Sexy Boy', 'שיר מוזר ומפתה עם קול רובוטי ופזמון שנדבק.'),
('All I Need', 'שיר אהבה עדין ושקט, עם קולה הרך של בת׳ הירש.'),
])

add(875, [
'''טאלווין סינג נולד בלונדון למשפחה ממוצא הודי, ובגיל צעיר נסע להודו כדי ללמוד לנגן על טבלה, תופי היד ההודיים, אצל מורה מסורתי. כשחזר ללונדון, הוא ניגן עם אמנים רבים, ביניהם ביורק, והקים בתחילת שנות התשעים ערב מועדון בשם "אנוקה", שהפך לבית של סצנה חדשה שנקראה "המחתרת האסייתית": צעירים בריטים ממוצא הודי ופקיסטני, שחיברו את המוזיקה של הוריהם עם דראם אנד בייס, היפ הופ ומוזיקה אלקטרונית. OK, אלבום הבכורה שלו, יצא ב־1998, ובשנה שאחריה זכה בפרס מרקורי.''',
'''המוזיקה מחברת עולמות שנשמעים רחוקים מאוד: טבלה, סיטאר, כינורות הודיים ושירה מסורתית, עם קצבים מהירים ושבורים של דראם אנד בייס, בס עמוק, צלילים אלקטרוניים וכלי מיתר מערביים. חלק מההקלטות נעשו בהודו, בעזרת מוזיקאים מקומיים, וחלקן בלונדון. Traveller, שפותח את האלבום, הוא מסע ארוך של יותר מעשר דקות, שמתחיל בכלי מיתר רכים ובשירה, ונבנה לאט לקצב מהיר וסוחף. Butterfly הוא קטע עדין ויפה עם סיטאר וקצב שבור, והשיר שנתן לאלבום את שמו ממשיך באותה רוח של מפגש בין מזרח למערב.''',
'''OK הפך לאחד האלבומים המייצגים של המוזיקה הבריטית־הודית של סוף שנות התשעים, יחד עם קורנרשופ (אלבום 849) וניטין סוואני (אלבום 888). הוא הראה שכלי נגינה בני מאות שנים יכולים להישמע חדשים לגמרי, והשפיע על מוזיקאים רבים שחיפשו דרך לחבר בין המסורת לבין המועדון.''',
'''הקשיבו ל־Traveller מההתחלה ועד הסוף, ושימו לב לטבלה שמנגנת מעל הקצב האלקטרוני. ואם אהבתם את The Sounds of India של ראבי שנקר (אלבום 111), תשמעו כאן את הדור הבא.''',
], [
('Traveller', 'מסע של יותר מעשר דקות, מכלי מיתר רכים לקצב מהיר וסוחף.'),
('Butterfly', 'קטע עדין ויפה עם סיטאר וקצב שבור.'),
('OK', 'מפגש בין מזרח למערב, עם טבלה וצלילים אלקטרוניים.'),
])

add(876, [
'''קורן הגיעו מבייקרספילד, עיירה חקלאית בקליפורניה, ובאמצע שנות התשעים המציאו כמעט לבד סגנון חדש, שנקרא אחר כך "נו מטאל": מטאל כבד ונמוך, עם גיטרות של שבעה מיתרים מכוונות נמוך מאוד, בס שמנגן בסגנון פאנק, קצבים של היפ הופ, ושירה שעוברת מלחישה לצעקה. הזמר, ג׳ונתן דייוויס, כתב שירים כואבים וחשופים על ילדות קשה ועל טראומה. Follow the Leader, האלבום השלישי שלהם, יצא בקיץ 1998, ונכנס ישר למקום הראשון במצעד האמריקאי.''',
'''הצליל כבד, מקפיץ ומאיים, עם ריפים פשוטים וחזקים, בס שמקיש כמו תוף, ותופים עם גרוב של היפ הופ. יש באלבום גם אורחים מעולם הראפ, כמו אייס קיוב, וזה מראה עד כמה קורן חיברו בין העולמות. Freak on a Leash, הלהיט הגדול, מתחיל בגיטרה מוזרה ומנצנצת, ונבנה לפיצוץ כבד, עם קטע באמצע שבו דייוויס שר בהברות חסרות משמעות במהירות מטורפת. הקליפ שלו, שמשלב אנימציה, זכה בגראמי. Got the Life הוא שיר מקפיץ, כמעט ריקודי, על הצד המעייף של ההצלחה. It's On! פותח את האלבום בעוצמה. יש גם עניין קטן ומוזר: באלבום המקורי, שתים עשרה הרצועות הראשונות הן שקט של כמה שניות, והמוזיקה מתחילה רק ברצועה השלוש עשרה.''',
'''Follow the Leader הפך את קורן לאחת הלהקות הגדולות בעולם, ופתח את הדלת לגל שלם של להקות נו מטאל בסוף שנות התשעים. המילים שלהם, על כאב ועל ניכור, דיברו אל דור שלם של בני נוער.''',
'''שמעו את Freak on a Leash, ושימו לב לקטע ההברות באמצע. ואם תרצו להשוות, Roots של ספולטורה (אלבום 820), שהופק באותה תקופה ובידי אותו מפיק כמו האלבומים הראשונים של קורן, חולק איתם הרבה.''',
], [
('Freak on a Leash', 'גיטרה מנצנצת שנבנית לפיצוץ כבד, עם קטע הברות מטורף.'),
('Got the Life', 'שיר מקפיץ, כמעט ריקודי, על הצד המעייף של ההצלחה.'),
("It's On!", 'פתיחה כבדה ועוצמתית, עם בס מקיש וצעקה.'),
])

add(877, [
'''שאב חאלד, שנקרא בפשטות חאלד, נולד באוראן שבאלג׳יריה, העיר שבה נולדה מוזיקת הראי: מוזיקה עממית ערבית, שהחלה כשירה של רועים ושל בתי מרזח, ובשנות השבעים והשמונים קיבלה צליל מודרני עם סינתיסייזרים, תופים אלקטרוניים ומילים נועזות על אהבה, יין וחופש. חאלד, שהתחיל לשיר כנער, הפך ל"מלך הראי", וב־1992 כבש את אירופה עם השיר Didi. בשנות התשעים הוא עזב את אלג׳יריה, שבה מוזיקאים הותקפו במלחמת האזרחים, ועבר לצרפת. Kenza, שנקרא על שם בתו השנייה, ושמו פירושו בערבית "אוצר", יצא בסוף 1999.''',
'''הצליל מחבר את הראי האלג׳ירי עם פופ צרפתי, פאנק, רגאיי ומוזיקה מצרית, עם כינורות, אקורדיון, כלי הקשה ערביים, כלי נשיפה וסינתיסייזרים. הקול של חאלד חזק, חם ומלא סלסולים, והוא שר בעיקר בערבית, עם מעט צרפתית. באלבום יש גרסה מרגשת לשיר Imagine של ג׳ון לנון, שחאלד שר יחד עם הזמרת הישראלית נועה, בערבית, בעברית ובאנגלית, כמסר של שלום. יש בו שירי ריקוד שמחים, ושירים כואבים על המולדת ועל הגלות.''',
'''Kenza הוא אחד האלבומים המצליחים של חאלד, והוא ממשיך את המסע שלו כאחד הזמרים הערבים המוכרים בעולם המערבי. הראי שלו נשמע בכל מקום, ממועדונים בפריז ועד חתונות בצפון אפריקה, והוא נשאר סמל לחיבור בין תרבויות. גם הדואט עם נועה הפך לסמל, ושני הזמרים ביצעו אותו בהופעות שונות כקריאה לשלום ולחיים משותפים.''',
'''שמעו את Imagine, והקשיבו לשני הקולות ולשלוש השפות. ואם אהבתם את Talking Timbuktu של עלי פרקה טורה וריי קודר (אלבום 773), תמצאו כאן צד אחר וקצבי של המוזיקה מצפון אפריקה.''',
], [
('Imagine', 'השיר של ג׳ון לנון בערבית, בעברית ובאנגלית, עם הזמרת נועה.'),
('El Bab', 'שיר ראי חזק ומרגש, עם קול חם ומלא סלסולים.'),
('Trigue Lycée', 'שיר ריקוד שמח ומקפיץ, עם כלי נשיפה וכלי הקשה.'),
])

add(878, [
'''קיד רוק, רוברט ריצ׳י, גדל ליד דטרויט שבמישיגן, ובשנות השמונים התחיל לתקלט ולעשות ראפ במסיבות. במשך כעשור הוא ניסה לפרוץ, הוציא כמה אלבומי ראפ שנכשלו, ונזרק מחברת התקליטים. אבל הוא לא ויתר: הוא חיבר את ההיפ הופ שאהב עם רוק כבד, רוק דרומי וקאנטרי, והקים להקה בשם Twisted Brown Trucker. Devil Without a Cause, שיצא ב־1998, נמכר בהתחלה לאט, ואז, בזכות הלהיט Bawitdaba וקליפים ב־MTV, הפך לתופעה ונמכר ביותר מעשרה מיליון עותקים.''',
'''המוזיקה היא תערובת רועשת ושמחה של ראפ רוק, עם גיטרות כבדות, תופים חזקים, ראפ מתגרה ויהיר, ומדי פעם גם צלילים של קאנטרי ורוק דרומי בסגנון לינירד סקינירד. קיד רוק מציג את עצמו כנוכל עממי, מצחיק וגס, ומתגאה בשורשים הפשוטים שלו. Bawitdaba, שיר הפתיחה, נפתח בקריאה של מילים חסרות משמעות והופך לפיצוץ רוק כבד ומקפיץ. Cowboy הוא שיר מצחיק ומקפיץ שמחבר ראפ עם גיטרות של מערבון ובנג׳ו, על גבר מהעיר שרוצה לכבוש את קליפורניה. Only God Knows Why הוא בלדה שקטה ומפתיעה, עם גיטרה אקוסטית, על תחושת ריקנות.''',
'''Devil Without a Cause הפך את קיד רוק לכוכב גדול, והיה אחד האלבומים המצליחים של גל הראפ רוק של סוף שנות התשעים. בהמשך הוא התקרב יותר ויותר לקאנטרי ולרוק דרומי, והפך לדמות מוכרת ושנויה במחלוקת באמריקה.''',
'''שמעו את Cowboy, ושימו לב לחיבור המוזר בין ראפ לבנג׳ו. ואחר כך עברו ל־Only God Knows Why, כדי לשמוע צד שקט ומפתיע. המילים באלבום בוטות לפעמים.''',
], [
('Bawitdaba', 'קריאה של מילים חסרות משמעות שהופכת לפיצוץ רוק כבד ומקפיץ.'),
('Cowboy', 'ראפ עם גיטרות של מערבון ובנג׳ו, מצחיק ומקפיץ.'),
('Only God Knows Why', 'בלדה שקטה ומפתיעה עם גיטרה אקוסטית, על ריקנות.'),
])

add(879, [
'''בורדס אוף קנדה הם שני אחים מסקוטלנד, מייקל סנדיסון ומרקוס אוין, שבילו חלק מילדותם בקנדה. השם שלהם לקוח מסרטים תיעודיים חינוכיים של המועצה הלאומית לקולנוע של קנדה, שהם צפו בהם כילדים, וזה בדיוק מה שהמוזיקה שלהם מעוררת: זיכרונות ילדות מטושטשים, של קלטות ישנות, תוכניות טלוויזיה לילדים ושמש של קיץ רחוק. Music Has the Right to Children, אלבום הבכורה שלהם, יצא ב־1998 בחברה הבריטית וורפ, אותה חברה של אפקס טווין (אלבום 708).''',
'''המוזיקה אלקטרונית, איטית וחמה, עם סינתיסייזרים ישנים שנשמעים קצת מזויפים ומעוותים, כאילו הוקלטו על קלטת שנמתחה. מתחת יש קצבים רכים של היפ הופ, ומעל קולות של ילדים, דגימות מסרטים חינוכיים ישנים וצלילים מוזרים. הכל נשמע נוסטלגי, יפה, וגם קצת מפחיד, כמו חלום שלא לגמרי זוכרים. Roygbiv הוא קטע קצר ומתוק עם מלודיה פשוטה וקצב רך, שנשמע כמו פתיחה של תוכנית ילדים. Aquarius הוא קטע מקפיץ ומוזר, עם קול של ילד וצלילים מצחיקים. Turquoise Hexagon Sun הוא קטע איטי, חם ומרחף, מהיפים באלבום.''',
'''Music Has the Right to Children הפך לאחד האלבומים המשפיעים ביותר במוזיקה האלקטרונית, והצליל הנוסטלגי והמטושטש שלו הועתק על ידי אינספור מוזיקאים. האחים עצמם נשארו מסתוריים, כמעט לא נותנים ראיונות ומוציאים מוזיקה לעתים רחוקות מאוד. הצליל שלהם השפיע לא רק על מוזיקאים אלקטרוניים, אלא גם על להקות רוק, על מלחינים לסרטים ועל אמנים חזותיים.''',
'''הקשיבו לאלבום באוזניות, בשעת ערב, ותנו לזיכרונות לעלות. השוו את הצליל ל־Selected Ambient Works 85–92 של אפקס טווין (אלבום 708).''',
], [
('Roygbiv', 'קטע קצר ומתוק עם מלודיה פשוטה, כמו פתיחה של תוכנית ילדים.'),
('Aquarius', 'קטע מקפיץ ומוזר, עם קול של ילד וצלילים מצחיקים.'),
('Turquoise Hexagon Sun', 'קטע איטי, חם ומרחף, מהיפים באלבום.'),
])

add(880, [
'''סובה, מיטאר סובוטיץ׳, היה מוזיקאי ומפיק מיוגוסלביה, שלמד מוזיקה קלאסית ומוזיקה אלקטרונית, והתאהב במוזיקה הברזילאית. בתחילת שנות התשעים הוא עבר לסאו פאולו, העיר הענקית של ברזיל, ושם נהיה אחד המפיקים המבוקשים, שחיבר בין המסורת הברזילאית לבין צלילים אלקטרוניים מודרניים. São Paulo Confessions, אלבום הסולו שלו, יצא ב־1999. זמן קצר לאחר מכן, בנובמבר אותה שנה, פרצה שריפה באולפן שלו, וסובה מת כשניסה להציל את ההקלטות של אלבום שהפיק לזמרת בבל ז׳ילברטו.''',
'''המוזיקה רכה, לילית ועירונית, כמו טיול בסאו פאולו אחרי חצות: קצבים של סמבה ובוסה נובה, גיטרה אקוסטית ופסנתר, יחד עם צלילים אלקטרוניים, קצבי דראם אנד בייס עדינים, וקולות רכים של זמרות ברזילאיות צעירות. Tantos Desejos, עם הזמרת סיבלה, הוא שיר רך ומפתה, עם קול לוחש מעל קצב אלקטרוני. Segredo הוא קטע לילי ויפה, עם שירה עדינה וצלילים מרחפים. Samba do Gringo Paulista, על "הזר מסאו פאולו", הוא קטע שמח וקצבי, שאולי מתאר את סובה עצמו, שהפך לחלק מהעיר.''',
'''São Paulo Confessions השפיע מאוד על מוזיקאים בברזיל ובעולם, שחיבר בין המוזיקה המסורתית של ברזיל לבין המועדון האלקטרוני. האלבום של בבל ז׳ילברטו, Tanto Tempo, יצא אחרי מותו של סובה והפך להצלחה עולמית, וכך המורשת שלו המשיכה לחיות. מי ששומע אותו היום מרגיש עד כמה הוא הקדים את זמנו, ואיזו הבטחה גדולה נקטעה עם מותו הפתאומי של סובה.''',
'''זה אלבום לערב חם, אולי עם חלון פתוח לעיר. ואם אהבתם את Clube da Esquina (אלבום 252), תשמעו כאן איך המוזיקה הברזילאית נשמעת שלושים שנה אחר כך, בעיר הגדולה.''',
], [
('Tantos Desejos', 'שיר רך ומפתה, עם קול לוחש של סיבלה מעל קצב אלקטרוני.'),
('Segredo', 'קטע לילי ויפה, עם שירה עדינה וצלילים מרחפים.'),
('Samba do Gringo Paulista', 'קטע שמח וקצבי על "הזר מסאו פאולו".'),
])

add(881, [
'''XTC מסווינדון שבאנגליה התחילו כלהקת ניו ווייב עצבנית בסוף שנות השבעים, אבל ב־1982 הזמר והכותב הראשי אנדי פרטרידג׳ סבל מפחד במה קשה, והלהקה הפסיקה להופיע לגמרי. מאז הם היו להקת אולפן בלבד, והוציאו אלבומי פופ מבריקים ומתוחכמים, כמו Skylarking (אלבום 579). בתחילת שנות התשעים הם נכנסו לסכסוך עם חברת התקליטים שלהם, ופשוט הפסיקו להקליט במשך כשבע שנים, עד שהשתחררו מהחוזה. Apple Venus Volume 1, שיצא בתחילת 1999, היה החזרה הגדולה שלהם.''',
'''זה אלבום תזמורתי ואקוסטי, כמעט בלי גיטרות חשמליות: כלי מיתר, כלי נשיפה, פסנתר, גיטרות אקוסטיות וקולות, עם מלודיות עשירות והרמוניות מורכבות, בהשראת הביטלס של התקופה המאוחרת ומוזיקה אנגלית כפרית. השירים עוסקים בטבע, באביב, באהבה ובפרידה. River of Orchids, שפותח את האלבום, הוא קטע מהפנט ומקורי, שבנוי מכלי מיתר בפריטה חוזרת, שמצטרפים זה לזה לאט, ושר על פרחים שצומחים באמצע הכביש. Easter Theatre הוא שיר חגיגי ויפה על האביב, עם תזמורת מלאה. I'd Like That הוא שיר אהבה קליל ומתוק, עם גיטרה אקוסטית. Your Dictionary, לעומת זאת, הוא שיר מר וכואב על גירושים.''',
'''Apple Venus Volume 1 נחשב לאחד האלבומים הטובים של XTC, ולאחד מאלבומי הפופ התזמורתי היפים של סוף המאה. בזמן ההקלטות עזב הגיטריסט דייב גרגורי את הלהקה, ונשארו רק פרטרידג׳ והבסיסט קולין מולדינג. שנה אחר כך יצא החלק השני, רועש וחשמלי יותר.''',
'''הקשיבו ל־River of Orchids באוזניות, ושימו לב איך כלי המיתר נכנסים אחד אחרי השני. והשוו את האלבום ל־Skylarking (אלבום 579), כדי לשמוע איך הלהקה התפתחה.''',
], [
('River of Orchids', 'כלי מיתר בפריטה חוזרת שמצטרפים לאט, על פרחים באמצע הכביש.'),
('Easter Theatre', 'שיר חגיגי ויפה על האביב, עם תזמורת מלאה.'),
("I'd Like That", 'שיר אהבה קליל ומתוק, עם גיטרה אקוסטית.'),
])

add(882, [
'''סקאנק אנאנסי היא להקה מלונדון שהוקמה באמצע שנות התשעים סביב הזמרת סקין, אישה שחורה, קירחת, בעלת קול עוצמתי ונוכחות במה מהפנטת. בתקופה שבה הרוק הבריטי היה בעיקר עניין של בחורים לבנים עם גיטרות, היא הייתה משהו חדש לגמרי, והלהקה שילבה רוק כבד, פאנק ופופ עם מילים פוליטיות ואישיות. Post Orgasmic Chill, האלבום השלישי שלהם, יצא באביב 1999, והיה המצליח ביותר שלהם, עם כמה שירים במצעד הבריטי.''',
'''הצליל של האלבום עובר בין רוק כבד ורועש, עם גיטרות חזקות ותופים מהירים, לבין בלדות רכות ויפות, עם כלי מיתר וקול שקט. הקול של סקין הוא הלב של הכל: היא יכולה לצעוק בעוצמה מטורפת, ושנייה אחר כך לשיר בעדינות מרגשת. Charlie Big Potato, שפותח את האלבום, הוא שיר רוק כבד ואפל, שמתחיל בשקט ונבנה לפיצוץ אדיר. Secretly הוא בלדה איטית ומפתה, שהופיעה גם בסרט אמריקאי מצליח. Lately הוא שיר רוק קליט ומלודי, עם פזמון גדול. יש באלבום גם שירים כועסים על גזענות, על יחסים ועל חברה שלא מקבלת את מי ששונה.''',
'''באותה שנה, 1999, סקין הייתה מהנשים השחורות הראשונות שעמדו בראש הבמה המרכזית בפסטיבל גלסטונברי, הפסטיבל הגדול של בריטניה. הלהקה התפרקה זמן קצר אחר כך, וחזרה כעבור כמה שנים, עם קהל נאמן במיוחד באירופה.''',
'''שמעו את Charlie Big Potato בקול רם, ושימו לב איך סקין עוברת מלחישה לצעקה. ואחר כך עברו ל־Secretly, כדי לשמוע את הצד הרך שלה. והשוו ל־Live Through This של הול (אלבום 774).''',
], [
('Charlie Big Potato', 'רוק כבד ואפל, שמתחיל בשקט ונבנה לפיצוץ אדיר.'),
('Secretly', 'בלדה איטית ומפתה, עם קול רך וכלי מיתר.'),
('Lately', 'רוק קליט ומלודי, עם פזמון גדול וקול חזק.'),
])

add(883, [
'''אינקובוס היא להקה מקלבסס, פרבר של לוס אנג׳לס, שהוקמה בתחילת שנות התשעים על ידי חברים מהתיכון. בתחילת דרכה היא ניגנה פאנק מטאל רועש ומקפיץ, בסגנון הרד הוט צ׳ילי פפרס, עם תקליטן ששורט תקליטים בתוך הלהקה. אבל ב־Make Yourself, האלבום השלישי שלהם, שיצא בסתיו 1999, הם הפכו מלודיים, רכים ובוגרים יותר, והזמר ברנדון בויד, עם קול חם וגמיש, הפך לפרצוף מוכר. האלבום נמכר במיליוני עותקים, בעיקר בזכות שיר אקוסטי אחד, שהפך ללהיט ענק.''',
'''השיר הזה הוא Drive, שיר שקט עם גיטרה אקוסטית ומלודיה יפה, על החלטה לא לתת לפחד לנהוג בחיים שלך. הוא הגיע למקום הראשון במצעד הרוק האלטרנטיבי באמריקה. אבל שאר האלבום מגוון: יש בו גיטרות כבדות, בס פאנקי, שריטות של תקליטן וצלילים אלקטרוניים, לצד בלדות רכות. Pardon Me הוא שיר רוק חזק ומתפוצץ, שנכתב בהשראת תמונה של אדם ש"נשרף מבפנים", כמשל לכעס כבוש. Stellar הוא שיר אהבה מרחף וחושני, עם גיטרות רחבות ופזמון גדול. Make Yourself, השיר שנתן לאלבום את שמו, הוא קריאה לבנות את עצמך ולא לחכות שאחרים יעשו את זה.''',
'''Make Yourself הפך את אינקובוס לאחת הלהקות הגדולות של הרוק האלטרנטיבי בתחילת שנות האלפיים, והראה שאפשר לצאת מגל הנו מטאל אל משהו מלודי ואישי יותר.''',
'''שמעו את Drive, ואחר כך את Pardon Me, ושימו לב לשני הצדדים של אותה להקה. השוו את האלבום ל־Californication של הרד הוט צ׳ילי פפרס (אלבום 900), שיצא באותה שנה.''',
], [
('Drive', 'שיר אקוסטי שקט ויפה, על החלטה לא לתת לפחד לנהוג בחיים.'),
('Pardon Me', 'רוק חזק ומתפוצץ, משל לכעס כבוש שבוער מבפנים.'),
('Stellar', 'שיר אהבה מרחף וחושני, עם גיטרות רחבות ופזמון גדול.'),
])

add(884, [
'''סטפין מריט, כותב שירים מניו יורק בעל קול עמוק ונמוך והומור יבש, ישב, לפי הסיפור, יום אחד בבר עם פסנתר, ושמע את הנגן מנגן שירים של כותבי ברודוויי הגדולים. הוא החליט שהוא רוצה לכתוב מופע ענק של מאה שירי אהבה, ובסוף הסתפק בשישים ותשעה. התוצאה, 69 Love Songs, יצאה ב־1999 בשלושה תקליטורים, עם כמעט שלוש שעות של מוזיקה, תחת השם של הלהקה שלו, המגנטיק פילדס. זה אחד האלבומים השאפתניים והאהובים של שנות התשעים.''',
'''הרעיון הוא לבחון את האהבה מכל כיוון אפשרי, ובכל סגנון מוזיקלי: יש כאן פולק, קאנטרי, סינת׳ פופ, פאנק, שירי ברודוויי, ג׳אז, גוספל ומוזיקה ניסיונית. מריט שר רבים מהשירים בקולו העמוק, אבל גם חברים שלו, גברים ונשים, מחליפים אותו. חלק מהשירים מצחיקים ואירוניים, חלקם עצובים וכנים, וחלקם פשוט מוזרים. Absolutely Cuckoo, שפותח את האלבום, הוא שיר קצר ומצחיק על מי שמזהיר את אהובתו שהוא מתאהב בטירוף. The Book of Love הוא שיר שקט ויפה, על ספר האהבה הארוך והמשעמם, ועל כך שבכל זאת רוצים שאהובנו יקרא אותו, והוא הפך לאחד השירים האהובים של מריט ונשמע מאז בהרבה חתונות. Papa Was a Rodeo הוא דואט קאנטרי מצחיק ונוגע ללב על אהבה בדרכים.''',
'''69 Love Songs הפך לאלבום פולחן, שנכנס לרשימות של הטובים של העשור, והוכיח שאלבום ענק יכול להיות גם קליל ומהנה. רבים רואים בו מעין אנציקלופדיה של שירי אהבה.''',
'''אל תנסו לשמוע את כל האלבום בבת אחת: הוא בנוי משלושה תקליטים, וכדאי לשמוע כל אחד בנפרד, בשלושה ערבים. התחילו ב־The Book of Love.''',
], [
('Absolutely Cuckoo', 'פתיחה קצרה ומצחיקה, אזהרה מפני התאהבות מטורפת.'),
('The Book of Love', 'שיר שקט ויפה על ספר האהבה, שנשמע מאז בהרבה חתונות.'),
('Papa Was a Rodeo', 'דואט קאנטרי מצחיק ונוגע ללב על אהבה בדרכים.'),
])

add(885, [
'''טראוויס היא להקה מגלזגו שבסקוטלנד, שהזמר והכותב שלה, פראן הילי, כותב שירים עדינים, מלנכוליים וכנים. אלבום הבכורה שלהם היה רוק בריטי רועש יחסית, אבל ב־The Man Who, שיצא באביב 1999, הם הפכו שקטים ורכים, עם גיטרות אקוסטיות, פסנתר ומלודיות נוגות. את האלבום הפיק בחלקו נייג׳ל גודריץ׳, המפיק של OK Computer (אלבום 837). בהתחלה הביקורות היו פושרות והמכירות איטיות, אבל אז, בפסטיבל גלסטונברי של קיץ 1999, קרה משהו שהפך לאגדה.''',
'''כשהלהקה ניגנה את Why Does It Always Rain on Me?, שיר על מי שהגשם תמיד יורד עליו, פתאום התחיל לרדת גשם על הקהל, אחרי יום שמשי, והרגע הזה הפך לסיפור שכולם סיפרו. השיר עלה במצעד, והאלבום הגיע למקום הראשון בבריטניה ונמכר במיליונים. המוזיקה רכה ומלודית, עם גיטרות אקוסטיות וחשמליות נקיות, פסנתר, כלי מיתר עדינים, ושירה פגיעה וגבוהה. Writing to Reach You, שפותח את האלבום, הוא שיר נוגה ויפה על מכתב לאדם רחוק. Driftwood הוא שיר מלודי וקליט על מי שנסחף בחיים בלי כיוון, ו־Turn הוא שיר גדול ומלא תקווה, עם פזמון שמזמין לשיר יחד.''',
'''The Man Who זכה בפרסי בריט לאלבום ולהקה הטובים ביותר, והשפיע מאוד על גל של להקות בריטיות רכות ומלודיות שבאו אחריו, כמו קולדפליי. הוא הראה שגם להקת גיטרות שקטה ורגישה יכולה למלא אצטדיונים.''',
'''שמעו את Why Does It Always Rain on Me?, ודמיינו את הגשם בגלסטונברי. והשוו את האלבום ל־OK Computer (אלבום 837), כדי לשמוע שני צדדים שונים מאוד של אותו מפיק.''',
], [
('Why Does It Always Rain on Me?', 'שיר על מי שהגשם תמיד יורד עליו, והגשם שירד בגלסטונברי.'),
('Writing to Reach You', 'שיר נוגה ויפה על מכתב לאדם רחוק.'),
('Driftwood', 'שיר מלודי וקליט על מי שנסחף בחיים בלי כיוון.'),
])

add(886, [
'''סליפנוט הגיעו מדה מוין, בירת איווה, מדינה חקלאית ושקטה באמצע ארצות הברית, שאיש לא ציפה שתצמח בה להקת מטאל. הם היו תשעה חברים, כולם במסכות מפחידות ובסרבלי עבודה עם מספרים מאפס עד שמונה, עם שני מתופפים נוספים, תקליטן ונגן דגימות. המסכות נועדו להסיט את תשומת הלב מהאנשים אל המוזיקה, אבל הפכו לסימן ההיכר שלהם. Slipknot, אלבום הבכורה, יצא ב־1999, בהפקת רוס רובינסון, המפיק של Roots של ספולטורה (אלבום 820), והפך להצלחה מפתיעה.''',
'''המוזיקה אגרסיבית, כאוטית ועוצמתית במיוחד: גיטרות כבדות ונמוכות, שלושה מתופפים שמכים יחד בפראות, שריטות של תקליטן וצלילים תעשייתיים, וצעקות זועמות של הזמר קורי טיילור. אבל בתוך הכאוס יש גם מלודיות ופזמונים. המילים מלאות זעם, ייאוש ותסכול של צעירים שמרגישים שאין להם מקום, והן בוטות מאוד. Wait and Bleed הוא השיר הנגיש ביותר, עם שילוב בין צעקות לשירה מלודית בפזמון, והוא היה מועמד לגראמי. Spit It Out הוא שיר מהיר וזועם שהפך לשיר החובה בהופעות. Surfacing הוא המנון מרד כועס על זרות, עם פזמון שקהל שלם צועק.''',
'''Slipknot היה האלבום הראשון של חברת התקליטים שלהם שנמכר במיליון עותקים באמריקה, והלהקה הפכה לאחת להקות המטאל הגדולות של שנות האלפיים. ההופעות שלהם, עם תשעה אנשים במסכות שמשתוללים על הבמה, הפכו לאגדה.''',
'''זה אלבום לחובבי מטאל כבד במיוחד. התחילו ב־Wait and Bleed, השיר המלודי ביותר. ואם אהבתם את Follow the Leader של קורן (אלבום 876), תשמעו כאן צד קיצוני יותר של אותה תקופה.''',
], [
('Wait and Bleed', 'שילוב בין צעקות לשירה מלודית בפזמון, השיר הנגיש ביותר.'),
('Spit It Out', 'שיר מהיר וזועם, שיר החובה בכל הופעה.'),
('Surfacing', 'המנון מרד כועס על זרות, עם פזמון שקהל שלם צועק.'),
])

add(887, [
'''בת׳ אורטון גדלה בכפר במזרח אנגליה, ואיבדה את שני הוריה כשהייתה צעירה מאוד. היא התחילה לשיר במקרה, כשהמפיק ויליאם אורביט, שלימים הפיק את Ray of Light של מדונה (אלבום 868), שמע אותה והזמין אותה להקליט. היא שרה גם עם הכימיקל בראדרס, למשל ב־Where Do I Begin מ־Dig Your Own Hole (אלבום 840). בסוף שנות התשעים היא פיתחה סגנון שנקרא "פולקטרוניקה": שירי פולק אקוסטיים, עם קצבים אלקטרוניים עדינים. Central Reservation, האלבום השלישי שלה, יצא ב־1999, וזיכה אותה בפרס בריט לזמרת הבריטית הטובה ביותר.''',
'''הלב של האלבום הוא הקול של אורטון, צרוד, חם ומעט שבור, וכתיבה כנה ואישית על אהבה, על בדידות ועל חיים בעיר. רוב השירים אקוסטיים, עם גיטרה, פסנתר, כלי מיתר וכלי נשיפה עדינים, ובחלקם נכנסים קצבים אלקטרוניים רכים. בין האורחים יש מוזיקאים כמו דוקטור ג׳ון ובן הארפר. Stolen Car, שפותח את האלבום, הוא שיר קצבי ומתגלגל, עם כלי נשיפה וגיטרה, על מערכת יחסים שהולכת לאיבוד. Sweetest Decline הוא שיר יפה ומלנכולי עם כלי מיתר, על הצד המתוק של הכאב. Central Reservation, השיר שנתן לאלבום את שמו, מופיע פעמיים: פעם בגרסה אקוסטית ופעם בגרסה אלקטרונית, שעשה בן וואט מאוורית׳ינג בט דה גירל (אלבום 826).''',
'''Central Reservation נחשב לאלבום הטוב של אורטון, ולאחד היפים של המוזיקה הבריטית בסוף שנות התשעים. הוא הראה שפולק ומוזיקה אלקטרונית יכולים להתחבר באופן טבעי ומרגש.''',
'''השוו בין שתי הגרסאות של Central Reservation, וחשבו איזו מתאימה לכם יותר. והקשיבו גם ל־Walking Wounded של אוורית׳ינג בט דה גירל (אלבום 826), שחולק איתה את אותה רוח.''',
], [
('Stolen Car', 'שיר קצבי ומתגלגל עם כלי נשיפה, על מערכת יחסים שהולכת לאיבוד.'),
('Sweetest Decline', 'שיר יפה ומלנכולי עם כלי מיתר, על הצד המתוק של הכאב.'),
('Central Reservation', 'שיר שקט ואישי, בקול צרוד וחם, עם גיטרה אקוסטית.'),
])

add(888, [
'''ניטין סוואני גדל בדרום מזרח אנגליה, בן להורים שהיגרו מהודו, וכילד למד פסנתר קלאסי, גיטרה פלמנקו, סיטאר וטבלה. בשנות התשעים הוא עבד כמוזיקאי, כמלחין לסרטים, וגם כקומיקאי בטלוויזיה הבריטית. Beyond Skin, שיצא ב־1999, היה מועמד לפרס מרקורי, ונחשב לאלבום החשוב שלו. הוא עוסק בזהות, בגזענות ובשאלה מה זה להיות בריטי ממוצא הודי, ובחלקו נכתב בתגובה לניסויים הגרעיניים של הודו ופקיסטן ב־1998, ולמתיחות הלאומנית סביבם.''',
'''המוזיקה מחברת עולמות רבים: גיטרת פלמנקו מהירה ועדינה, שירה הודית מסורתית, טבלה, כלי מיתר, קצבים של דראם אנד בייס ושל טריפ הופ, וג׳אז. בין השירים יש דגימות של קולות, כולל נאומים של פוליטיקאים ומדענים על פצצות ועל לאומיות, וקולות של משפחתו של סוואני. התוצאה נשמעת יפה, רגועה ומרגשת, אבל גם מלאה מחשבה. Nadia, עם הזמרת סוואטי נאטקר, הוא שיר יפה במיוחד, ששירה הודית מסורתית מרחפת בו מעל קצב דראם אנד בייס מהיר. Letting Go הוא שיר רך ומלנכולי עם גיטרה אקוסטית. Broken Skin הוא קטע מהיר ואנרגטי, שמחבר גיטרת פלמנקו עם קצב אלקטרוני.''',
'''Beyond Skin הפך לאחד האלבומים החשובים של המוזיקה הבריטית־אסייתית, לצד OK של טאלווין סינג (אלבום 875) וקורנרשופ (אלבום 849). סוואני המשיך לקריירה עשירה כמלחין לסרטים, לתיאטרון ולמחול. הוא נשמע אישי מאוד, כמו מכתב של בן מהגרים לארץ שבה גדל ולארץ שממנה באו הוריו.''',
'''הקשיבו ל־Nadia באוזניות, ושימו לב איך השירה המסורתית והקצב המהיר מתחברים. ואחר כך עברו ל־Broken Skin, כדי לשמוע את גיטרת הפלמנקו.''',
], [
('Nadia', 'שירה הודית מסורתית מרחפת מעל קצב דראם אנד בייס מהיר.'),
('Letting Go', 'שיר רך ומלנכולי, עם גיטרה אקוסטית וקול עדין.'),
('Broken Skin', 'גיטרת פלמנקו מהירה מעל קצב אלקטרוני אנרגטי.'),
])

add(889, [
'''דת׳ אין וגאס התחילה באמצע שנות התשעים כפרויקט של התקליטן ריצ׳רד פירלס, שחיבר מוזיקה אלקטרונית עם רוק פסיכדלי ודאב. בהמשך הצטרף אליו המהנדס טים הולמס, והשניים בנו צליל אפל, כבד ומהפנט. The Contino Sessions, שיצא ב־1999, הוא האלבום שבו הם הגיעו לשיא, עם רשימה מרשימה של זמרים אורחים: איגי פופ מהסטוג׳ז (אלבום 171), בובי גילספי מפריימל סקרים (אלבום 841), וג׳ים ריד מהג׳יזס אנד מרי צ׳יין (אלבום 559). האלבום היה מועמד לפרס מרקורי.''',
'''המוזיקה נשמעת כמו הצד האפל של סוף שנות התשעים: בס עמוק, גיטרות פסיכדליות ורועשות, תופים כבדים בסגנון קראוטרוק, אורגן, צלילים אלקטרוניים ואווירה של מועדון לילה מעושן. Dirge, עם הזמרת דוט אליסון, הוא קטע מהפנט שבנוי על קריאה חוזרת פשוטה, "לה לה לה", שנבנית לאט לאט לפיצוץ אדיר של גיטרות. הוא הפך ללהיט אחרי שהופיע בפרסומת מפורסמת. Aisha, עם איגי פופ, הוא שיר מאיים ומפחיד, שבו פופ מדבר כמו רוצח מסרט אימה. Soul Auctioneer, עם בובי גילספי, הוא שיר אפל ומסתורי, עם בס עמוק וקול לוחש.''',
'''The Contino Sessions הוא אחד האלבומים המעניינים שחיברו בין מוזיקה אלקטרונית לבין רוק בסוף שנות התשעים, והוא נשמע עד היום כבד, אפל ומפתה. דת׳ אין וגאס המשיכו להוציא אלבומים, ופירלס עבד עם אמנים רבים כמפיק.''',
'''שמעו את Dirge מההתחלה ועד הסוף, ושימו לב איך שתי מילים פשוטות הופכות לפיצוץ. ואם אהבתם את Vanishing Point של פריימל סקרים (אלבום 841), תמצאו כאן אותו עולם אפל.''',
], [
('Dirge', 'קריאה פשוטה וחוזרת שנבנית לאט לפיצוץ אדיר של גיטרות.'),
('Aisha', 'איגי פופ מדבר כמו רוצח מסרט אימה, מאיים ומפחיד.'),
('Soul Auctioneer', 'בובי גילספי בשיר אפל ומסתורי, עם בס עמוק.'),
])

add(890, [
'''מובי, ריצ׳רד מלוויל הול, הוא מוזיקאי מניו יורק, נצר רחוק של הסופר הרמן מלוויל, מחבר מובי דיק, ומכאן הכינוי שלו. בתחילת שנות התשעים הוא היה אחד מכוכבי הטכנו והרייב, אבל אחר כך הוציא אלבומים שנכשלו, והקריירה שלו נראתה גמורה. Play, שיצא באביב 1999, התחיל גם הוא לאט, וכמעט לא נמכר. ואז קרה דבר חסר תקדים: כל אחד מהשירים באלבום קיבל רישיון לפרסומת, לסרט או לסדרה, והמוזיקה נשמעה פתאום בכל מקום. האלבום נמכר בסוף ביותר מעשרה מיליון עותקים.''',
'''הרעיון המרכזי של Play הוא חיבור בין העבר להווה: מובי לקח הקלטות שדה ישנות של זמרי בלוז וגוספל אפרו־אמריקאים, שהוקלטו בדרום ארצות הברית בתחילת המאה העשרים, והניח אותן מעל קצבים אלקטרוניים, פסנתר וכלי מיתר. Natural Blues בנוי על קולה של זמרת עממית שהוקלטה בשנות השלושים, ששרה על צרות ועל אמונה, מעל קצב היפ הופ ופסנתר. Porcelain, שבו מובי שר בעצמו, הוא שיר שקט ומרחף, עם כלי מיתר וקול לוחש, על פרידה. Why Does My Heart Feel So Bad? הוא קטע עצוב ויפה, עם קולות של מקהלת גוספל ופסנתר.''',
'''Play הפך לאחד האלבומים הנמכרים של המוזיקה האלקטרונית, והביא את הקולות של זמרי הבלוז הנשכחים לדור חדש. היו גם שביקרו אותו על כך שהשתמש בקולות של אחרים, וכל הדיון הזה עוד חי עד היום.''',
'''שמעו את Natural Blues, ונסו לדמיין את הזמרת המקורית שרה לבד, בלי הקצב. והשוו את Play ל־Endtroducing של די ג׳יי שאדו (אלבום 815), עוד אלבום שנבנה מתקליטים של אחרים.''',
], [
('Natural Blues', 'קולה של זמרת עממית משנות השלושים, מעל קצב היפ הופ ופסנתר.'),
('Porcelain', 'שיר שקט ומרחף עם כלי מיתר וקול לוחש, על פרידה.'),
('Why Does My Heart Feel So Bad?', 'קטע עצוב ויפה, עם קולות של מקהלת גוספל ופסנתר.'),
])

add(891, [
'''הפליימינג ליפס מאוקלהומה סיטי היו במשך יותר מעשור להקה מוזרה, רועשת ומשעשעת, שעשתה רוק אלטרנטיבי פסיכדלי ומבולגן, עם להיט אחד מצליח באמצע שנות התשעים. הזמר וויין קוין אהב ניסויים: לפני כן הוציאו אלבום של ארבעה תקליטורים שצריך להשמיע בבת אחת, בארבע מערכות שמע. אבל The Soft Bulletin, שיצא ב־1999, היה משהו אחר לגמרי: אלבום תזמורתי, רגשי ויפה, שהשווה אותם לביטלס ולביץ׳ בויז, ונבחר בעיני מבקרים רבים לאלבום הטוב של השנה.''',
'''את האלבום הפיק דייב פרידמן, שעבד גם על Deserter's Songs של מרקורי רב (אלבום 871), והמוזיקה מלאה בכלי מיתר, פעמונים, פסנתר, תופים ענקיים ומהדהדים וקולות רבים, הרבה מהם מנוגנים על ידי סטיבן דרוזד, נגן מוכשר במיוחד. השירים עוסקים בחיים ובמוות, במדע, באהבה ובפחד מאובדן, בקולו הגבוה והשביר של קוין. Race for the Prize, שפותח את האלבום, הוא שיר אדיר עם כלי מיתר ותופים, על שני מדענים שמתחרים מי ימצא ראשון תרופה למחלה, ומוכנים להקריב הכל. Waitin' for a Superman הוא שיר עדין ונוגה, עם פסנתר, על כך שגם סופרמן לא יכול להרים את השמש. A Spoonful Weighs a Ton הוא שיר רחב ומרגש על כוחו של מעשה קטן.''',
'''The Soft Bulletin נחשב לאחד האלבומים החשובים של סוף שנות התשעים, והפך את הפליימינג ליפס מלהקה מוזרה ללהקה אהובה, עם הופעות צבעוניות ומשמחות מלאות קונפטי, בלונים ותחפושות. הוא השפיע על להקות רבות שחיפשו צליל גדול, תזמורתי ורגשי.''',
'''שמעו את Race for the Prize בקול רם, ושימו לב לתופים הענקיים. והשוו את האלבום ל־Pet Sounds של הביץ׳ בויז (אלבום 61), שרבים ראו בו את ההשראה שלו.''',
], [
('Race for the Prize', 'שיר אדיר עם כלי מיתר ותופים, על מדענים שמתחרים למצוא תרופה.'),
("Waitin' for a Superman", 'שיר עדין ונוגה עם פסנתר, על כך שגם סופרמן לא יכול הכל.'),
('A Spoonful Weighs a Ton', 'שיר רחב ומרגש על כוחו של מעשה קטן.'),
])

add(892, [
'''לה ריתם דיז׳יטאל היה בעצם בריטי צעיר בשם סטיוארט פרייס, שהציג את עצמו בבדיחה כצרפתי בשם ז׳אק לו קונט, עם מבטא צרפתי מזויף בראיונות. בסוף שנות התשעים, כשכולם עשו מוזיקה אלקטרונית כבדה ורצינית, פרייס התאהב דווקא בפופ האלקטרוני הנוצץ של שנות השמונים, עם סינתיסייזרים צבעוניים, מכונות תופים ישנות ומלודיות קליטות. Darkdancer, שיצא ב־1999, היה מחווה שמחה ומצחיקה לתקופה הזאת, הרבה לפני שהשמונים חזרו לאופנה.''',
'''המוזיקה היא מסיבה של שנות השמונים: סינתיסייזרים בוהקים, בס אלקטרוני מקפיץ, תופים מכניים, קולות מעובדים ופזמונים שמחים, עם השפעה של פופ, אלקטרו, האוס ודיסקו. Jacques Your Body (Make Me Sweat) הוא שיר ריקוד שמח ומקפיץ, עם קול מעובד וקצב בלתי ניתן לעצירה, שהפך ללהיט גדול כמה שנים אחר כך, כשהופיע בפרסומת. Sometimes, שבו שר ניק קרשו, כוכב פופ בריטי של שנות השמונים, הוא שיר פופ מתוק ונוסטלגי שנשמע כאילו יצא באמת ב־1985. (Hey You) What's That Sound? הוא קטע אלקטרו מהיר עם קולות רובוטיים.''',
'''Darkdancer היה אחד הסימנים הראשונים לחזרה הגדולה של פופ שנות השמונים, ולסגנון שנקרא אחר כך "אלקטרוקלאש". סטיוארט פרייס הפך בהמשך לאחד המפיקים המבוקשים בעולם, והפיק אלבומים לכוכבים כמו מדונה, הקילרז וקיילי מינוג. כאן אפשר לשמוע איפה הכל התחיל.''',
'''שמעו את Sometimes, ונסו לנחש אם הוא באמת משנות השמונים. ואחר כך עברו ל־Jacques Your Body (Make Me Sweat), ותנו לעצמכם לרקוד. והשוו ל־Homework של דאפט פאנק (אלבום 850).''',
], [
('Jacques Your Body (Make Me Sweat)', 'שיר ריקוד שמח ומקפיץ, עם קול מעובד וקצב שלא נעצר.'),
('Sometimes', 'פופ מתוק ונוסטלגי עם ניק קרשו, כאילו יצא באמת ב־1985.'),
("(Hey You) What's That Sound?", 'אלקטרו מהיר עם קולות רובוטיים וסינתיסייזרים בוהקים.'),
])

add(893, [
'''קתלין האנה הייתה הזמרת של ביקיני קיל, אחת הלהקות החשובות של תנועת הריוט גרל, פאנק פמיניסטי כועס מתחילת שנות התשעים, שהשפיע גם על סלייטר־קיני (אלבום 844). כשהלהקה התפרקה, היא הקימה את לה טיגר עם האמנית ג׳והנה פייטמן ועם יוצרת הסרטים סיידי בנינג. במקום גיטרות רועשות ותופים, הן השתמשו בדוגמים, במכונות תופים ובסינתיסייזרים זולים, וחיברו פאנק עם מוזיקת ריקודים. Le Tigre, אלבום הבכורה שלהן, יצא ב־1999.''',
'''המוזיקה פשוטה, שמחה, רועשת ומלאה בהומור, כמו מסיבה של אמניות פמיניסטיות, עם קצבים אלקטרוניים מקפיצים, גיטרות קצרות, שירה וצעקות של שלוש הנשים יחד. המילים חכמות ופוליטיות, אבל גם מצחיקות מאוד. Deceptacon, שפותח את האלבום, הוא שיר ריקוד פרוע עם צעקה מפורסמת שמשחקת בשיר פופ ישן, והפך לשיר הכי מוכר שלהן, שנשמע עד היום בסרטים ובמסיבות. Hot Topic הוא שיר שמח שכולו רשימה של שמות של אמניות, סופרות ומוזיקאיות פמיניסטיות, כמו מחווה לגיבורות. My My Metrocard הוא שיר מצחיק על הרכבת התחתית של ניו יורק ועל כרטיס הנסיעה.''',
'''Le Tigre הפך לאלבום פולחן, והשפיע על גל של להקות שחיברו פאנק עם מוזיקה אלקטרונית בתחילת שנות האלפיים. הוא הראה שמוזיקה פוליטית ופמיניסטית יכולה להיות גם שמחה, מצחיקה ומרקידה. השילוב בין מסר רציני לבין הומור וקצב שמח הוא בדיוק מה שהופך אותו לרענן גם היום.''',
'''שמעו את Deceptacon בקול רם, ונסו לא לרקוד. ואחר כך הקשיבו ל־Hot Topic, ונסו לזהות כמה שמות ברשימה. והשוו ל־Dig Me Out של סלייטר־קיני (אלבום 844).''',
], [
('Deceptacon', 'שיר ריקוד פרוע עם צעקה מפורסמת, השיר המוכר ביותר שלהן.'),
('Hot Topic', 'שיר שמח שכולו רשימה של אמניות ויוצרות פמיניסטיות.'),
('My My Metrocard', 'שיר מצחיק על הרכבת התחתית של ניו יורק.'),
])

add(894, [
'''מרשל מת׳רס, אמינם, גדל בעוני בדטרויט ובסביבתה, עם אם חד הורית ומעברי דירה רבים, ובשכונות שבהן ראפר לבן היה דבר נדיר מאוד. אלבום הבכורה שלו, ב־1996, נכשל לגמרי, אבל ב־1997 הוא זכה במקום השני בתחרות ראפ חשובה בלוס אנג׳לס, וקלטת ההדגמה שלו הגיעה לדוקטור דרה (אלבום 717). דרה החתים אותו, ו־The Slim Shady LP, שיצא בתחילת 1999, הפך אותו בבת אחת לכוכב. השם לקוח מהדמות שהמציא, סלים שיידי, הצד הפרוע, האכזרי והמצחיק שלו.''',
'''הקצבים, חלקם של דרה, פשוטים, פאנקיים וקליטים, אבל הכוכב הוא הראפ של אמינם: מהיר, חד, מלא חרוזים מסובכים, ובעיקר מצחיק בצורה פרועה ומזעזעת. הוא צוחק על עצמו, על המשפחה שלו, על כוכבים מפורסמים ועל כל מה שאסור. My Name Is, הלהיט הגדול, הוא הצגה עצמית מצחיקה ומשוגעת, עם קצב פאנקי וקריאה חוזרת שכולם זוכרים. Guilty Conscience הוא דואט עם דרה, שבו שניהם מגלמים את המלאך והשטן שעל הכתף של אנשים שעומדים לעשות משהו רע. Rock Bottom הוא שיר רציני ועצוב, על עוני ועל ייאוש, שמראה צד אחר שלו. המילים באלבום בוטות מאוד, וחלקן עוררו ביקורת חריפה.''',
'''The Slim Shady LP זכה בגראמי לאלבום הראפ הטוב ביותר, ופתח קריירה שהפכה את אמינם לאחד הראפרים הנמכרים בתולדות המוזיקה. הוא הראה שראפר לבן יכול להצליח בזכות כישרון אמיתי ולא בגלל צבע העור.''',
'''שמעו את Guilty Conscience, ושימו לב לשיחה בין שני הקולות. והשוו ל־The Chronic של דוקטור דרה (אלבום 717), כדי לשמוע מאיפה הגיעו הקצבים.''',
], [
('My Name Is', 'הצגה עצמית מצחיקה ומשוגעת, עם קצב פאנקי וקריאה שכולם זוכרים.'),
('Guilty Conscience', 'דואט עם דרה, המלאך והשטן שעל הכתף.'),
('Rock Bottom', 'שיר רציני ועצוב על עוני וייאוש, צד אחר של אמינם.'),
])

add(895, [
'''בריטני ספירס גדלה בעיירה קטנה בלואיזיאנה, וכבר כילדה הופיעה בתחרויות כישרונות ובתוכנית הטלוויזיה של מועדון מיקי מאוס, לצד ילדים שהפכו גם הם לכוכבים, כמו ג׳סטין טימברלייק. בגיל שבע עשרה היא הוציאה את אלבום הבכורה שלה, ...Baby One More Time, בתחילת 1999. הוא נכנס ישר למקום הראשון במצעד האמריקאי, והשיר הראשון בו הגיע למקום הראשון בעשרות ארצות. בריטני הפכה בתוך שבועות לכוכבת הפופ הגדולה בעולם, ולסמל של סוף שנות התשעים.''',
'''את רוב השירים כתבו והפיקו מקס מרטין ומפיקים שוודים אחרים מאולפן בשטוקהולם, אותם מפיקים שעבדו עם להקות בנים מצליחות. הם בנו שירי פופ מדויקים ומלוטשים, עם קצבים חזקים, פסנתר, גיטרות ופזמונים שאי אפשר לשכוח, והקול של בריטני, נמוך, מתפתל ומעט צרוד, הפך לסימן ההיכר שלה. ...Baby One More Time, שיר הפתיחה, נפתח בשלושה צלילי פסנתר מפורסמים, והוא אחד משירי הפופ המוכרים בתולדות המוזיקה. (You Drive Me) Crazy הוא שיר פופ שמח ומקפיץ, ו־Sometimes הוא בלדה עדינה ומתוקה על אהבה ביישנית.''',
'''...Baby One More Time הוא אחד האלבומים הנמכרים של כל הזמנים לזמרת צעירה, ופתח עידן חדש של כוכבות פופ צעירות. השיר הראשי אהוב גם על מוזיקאים מעולמות אחרים לגמרי: להקת טראוויס (אלבום 885), למשל, ביצעה לו גרסה אקוסטית ושקטה.''',
'''הקשיבו לשלושת צלילי הפסנתר בתחילת השיר הראשי, ונסו לחשוב על שיר פופ אחר שנפתח בצורה מזוהה כל כך. ואחר כך עברו ל־Sometimes, כדי לשמוע את הצד הרך.''',
], [
('...Baby One More Time', 'שלושה צלילי פסנתר מפורסמים, ואחד משירי הפופ המוכרים בהיסטוריה.'),
('(You Drive Me) Crazy', 'שיר פופ שמח ומקפיץ, עם פזמון שאי אפשר לשכוח.'),
('Sometimes', 'בלדה עדינה ומתוקה על אהבה ביישנית.'),
])

add(896, [
'''מטאליקה, להקת המטאל הגדולה בעולם, תמיד אהבה מוזיקה קלאסית: היא כתבה קטעים כליים ארוכים ומורכבים, ומוזיקה של אניו מוריקונה פתחה את ההופעות שלה. ב־1999 הם הגשימו רעיון שנראה מטורף: שתי הופעות משותפות עם התזמורת הסימפונית של סן פרנסיסקו, בעיבודים של המלחין והמנצח מייקל קיימן, שעבד קודם עם פינק פלויד וכתב מוזיקה לסרטים רבים. S&M, קיצור של סימפוניה ומטאליקה, הוקלט באפריל 1999 בתיאטרון בברקלי, ויצא בסוף השנה כאלבום כפול.''',
'''כאן נשמעים השירים המוכרים של מטאליקה, משנות השמונים ועד סוף התשעים, עם עשרות נגני כלי מיתר, נשיפה והקשה מסביב, שמוסיפים להם עוצמה דרמטית, כמו פסקול לסרט אפי. ההופעה נפתחת ב־The Ecstasy of Gold, הקטע של אניו מוריקונה מהמערבון "הטוב, הרע והמכוער", שמטאליקה נוהגים לעלות לבמה לצליליו. The Call of Ktulu, קטע כלי ארוך מתחילת דרכם, נשמע כאן כמו יצירה קלאסית של ממש, והגרסה הזאת זכתה בגראמי. Nothing Else Matters, הבלדה המפורסמת מ־Metallica (אלבום 706), נשמעת עם התזמורת עדינה ומרגשת עוד יותר. No Leaf Clover הוא אחד משני שירים חדשים שנכתבו במיוחד להופעה.''',
'''S&M נמכר במיליוני עותקים, והראה שמטאל ומוזיקה קלאסית חולקים יותר ממה שחושבים: דרמה, עוצמה, מבנים ארוכים ורגש גדול. עשרים שנה אחר כך, ב־2019, מטאליקה והתזמורת חזרו לעשות זאת שוב. מעריצי מטאל רבים גילו בזכותו את המוזיקה הקלאסית, וחובבי מוזיקה קלאסית רבים גילו את מטאליקה.''',
'''השוו את Master of Puppets כאן לגרסה המקורית ב־Master of Puppets (אלבום 567), ושימו לב למה שהתזמורת מוסיפה. והתחילו ב־The Call of Ktulu.''',
], [
('The Call of Ktulu', 'קטע כלי ארוך שנשמע כמו יצירה קלאסית, וזכה בגראמי.'),
('Nothing Else Matters', 'הבלדה המפורסמת, עדינה ומרגשת עוד יותר עם התזמורת.'),
('No Leaf Clover', 'שיר חדש שנכתב במיוחד להופעה, עם פתיחה תזמורתית.'),
])

add(897, [
'''וויל אולדהם גדל בלואיוויל שבקנטקי, וכנער היה שחקן בסרטים, לפני שפנה למוזיקה. בשנות התשעים הוא הוציא אלבומים רבים תחת שמות משתנים, כמעט תמיד עם המילה "פאלאס", שירי פולק וקאנטרי שקטים, מוזרים ואפלים. ב־1998 הוא המציא דמות חדשה, בוני "פרינס" בילי, ו־I See a Darkness, שיצא בתחילת 1999, היה האלבום הראשון שלה, ונחשב לטוב ביותר שלו. אולדהם עצמו מעדיף להישאר מסתורי, כמעט לא מדבר על חייו, ומתייחס למוזיקה כמו לעבודה של אומן.''',
'''המוזיקה שקטה, פשוטה ועמוקה, עם גיטרה אקוסטית, פסנתר, אורגן, תופים עדינים וקולות רקע, והקול של אולדהם, גבוה, רועד ושביר, כמו של זמר עם כפרי ישן. השירים עוסקים במוות, בבדידות, בחברות, באמונה ובחושך שבתוך כל אחד, אבל יש בהם גם חום והומור יבש. I See a Darkness, השיר שנתן לאלבום את שמו, הוא שיר על אדם שמבקש מחברו לעזור לו מול החושך שהוא רואה. ג׳וני קאש הקליט אותו שנה אחר כך, עם אולדהם בקולות רקע, והפך אותו לאחד השירים המפורסמים של סוף ימיו. Black הוא שיר שקט ומהורהר עם פסנתר, ו־Madeleine-Mary הוא שיר מתוק ומוזר, עם מלודיה יפה.''',
'''I See a Darkness נחשב לאחד מאלבומי הפולק האמריקאי החשובים של סוף שנות התשעים, והשפיע על דור שלם של זמרים־כותבים עצמאיים. אולדהם ממשיך עד היום להוציא אלבומים רבים, תמיד בדרכו הייחודית.''',
'''שמעו את I See a Darkness בשקט, ואחר כך חפשו את הגרסה של ג׳וני קאש והשוו. ואם אהבתם את Either/Or של אליוט סמית׳ (אלבום 856), תמצאו כאן נשמה קרובה.''',
], [
('I See a Darkness', 'אדם מבקש מחברו לעזור לו מול החושך, שיר שג׳וני קאש הקליט אחר כך.'),
('Black', 'שיר שקט ומהורהר עם פסנתר וקול שביר.'),
('Madeleine-Mary', 'שיר מתוק ומוזר, עם מלודיה יפה וגיטרה אקוסטית.'),
])

add(898, [
'''שאק היא להקה מליברפול שהקימו שני אחים, מייקל וג׳ון הד, שכבר בשנות השמונים ניגנו בלהקה מוערכת בשם פייל פאונטנס. הסיפור שלהם מלא במזל רע: התמכרויות, חברות תקליטים שפשטו את הרגל, ואפילו שריפה באולפן שהשמידה את ההקלטות המקוריות של אחד מהאלבומים שלהם. H.M.S. Fable, שיצא ב־1999, עוכב כמה פעמים, אבל כשהוא יצא, הוא זכה לשבחים גדולים, והביא סוף סוף את שאק לתשומת לב רחבה יותר בבריטניה.''',
'''המוזיקה היא פופ גיטרות קלאסי ויפה, בהשראת להקות של שנות השישים, ובמיוחד לאב והאלבום Forever Changes (אלבום 87), שמייקל הד מעריץ גדול שלו. יש כאן גיטרות אקוסטיות וחשמליות מצלצלות, חצוצרות, כלי מיתר, הרמוניות ומלודיות עשירות, וקולו הרך והמעט צרוד של מייקל הד. השירים מלאים בתמונות מחיי היומיום בליברפול: רחובות, חברים, מסיבות ואהבות. Comedy, הלהיט הגדול, הוא שיר אהבה יפה ומתוק, עם גיטרה מצלצלת ופזמון חם. Natalie's Party הוא שיר שמח וקליל על מסיבה, עם מלודיה שנדבקת. Pull Together הוא שיר אופטימי ומלא תקווה, על חברים שעוזרים זה לזה.''',
'''למרות השבחים, שאק אף פעם לא הפכה ללהקה גדולה, ונשארה סוד שמוכר בעיקר לאוהבי מוזיקה בבריטניה. אבל רבים רואים במייקל הד אחד מכותבי השירים הטובים והפחות מוכרים של דורו, ו־H.M.S. Fable הוא הכניסה הטובה לעולם שלו. מבקרים בריטיים רבים מזכירים אותו עד היום כאחד האלבומים היפים והמוערכים פחות מדי של שנות התשעים.''',
'''אם אהבתם את Forever Changes של לאב (אלבום 87), שמעו את Comedy והשוו. וזה אלבום טוב לבוקר קיצי ורגוע.''',
], [
('Comedy', 'שיר אהבה יפה ומתוק, עם גיטרה מצלצלת ופזמון חם.'),
("Natalie's Party", 'שיר שמח וקליל על מסיבה, עם מלודיה שנדבקת.'),
('Pull Together', 'שיר אופטימי ומלא תקווה, על חברים שעוזרים זה לזה.'),
])

add(899, [
'''בייסמנט ג׳קס הם פליקס בקסטון וסיימון ראטקליף, שני תקליטנים ומפיקים מבריקסטון שבדרום לונדון, שכונה עם קהילה גדולה של מהגרים מהאיים הקריביים ומאפריקה. באמצע שנות התשעים הם התחילו לארגן מסיבות במרתף, ומכאן השם, והוציאו תקליטי האוס שהפכו לאהובים במועדונים. Remedy, אלבום הבכורה שלהם, יצא ב־1999, היה מועמד לפרס מרקורי, ונחשב לאחד האלבומים השמחים והצבעוניים ביותר של מוזיקת הריקודים הבריטית.''',
'''הבסיס הוא מוזיקת האוס, אבל בייסמנט ג׳קס מערבבים לתוכה כמעט כל דבר: גיטרות פלמנקו, קצבים לטיניים, רגאיי וראגה, גוספל, דיסקו, פאנק וסול, עם קולות של זמרים וראפרים מהשכונה. התוצאה נשמעת כמו מסיבת רחוב ענקית ומבולגנת, מלאת שמחה ואנרגיה. Red Alert, הלהיט הגדול, הוא שיר ריקוד פאנקי ושמח, עם בס מקפיץ וקול שקורא לכולם לקום. Rendez-Vu נפתח בגיטרת פלמנקו מהירה והופך למסיבה לטינית סוחפת. Jump N' Shout הוא קטע פרוע ומהיר, עם ראגה ג׳מייקנית וקצב שלא נותן לעמוד במקום.''',
'''Remedy הביא את מוזיקת ההאוס מהמועדון אל הבית ואל המצעדים, והראה שהיא יכולה להיות מגוונת, צבעונית ומלאת הומור. בייסמנט ג׳קס המשיכו לאלבומים ולהיטים רבים, והפכו לאחד הצמדים האלקטרוניים האהובים של שנות האלפיים. הם גם הוכיחו שמוזיקה אלקטרונית יכולה להישמע אנושית, חמה ומלאה בצבעים של שכונה אמיתית, ולא רק של מכונות. ההופעות שלהם, עם זמרים, רקדנים ותלבושות, הפכו לחגיגות צבעוניות.''',
'''שמעו את Rendez-Vu, ושימו לב איך גיטרת הפלמנקו פוגשת את קצב ההאוס. והשוו ל־Homework של דאפט פאנק (אלבום 850), כדי לשמוע שתי דרכים שונות לעשות האוס באותן שנים.''',
], [
('Red Alert', 'שיר ריקוד פאנקי ושמח, עם בס מקפיץ וקול שקורא לקום.'),
('Rendez-Vu', 'גיטרת פלמנקו מהירה שהופכת למסיבה לטינית סוחפת.'),
("Jump N' Shout", 'קטע פרוע ומהיר, עם ראגה ג׳מייקנית וקצב שלא נעצר.'),
])

add(900, [
'''הרד הוט צ׳ילי פפרס מלוס אנג׳לס התחילו בשנות השמונים כלהקת פאנק רוק פרועה, מקפיצה וחשופה, עם הבסיסט פלי, שמנגן בסגנון הקשה מהיר ומדהים, והזמר אנתוני קידיס. אחרי הצלחה גדולה בתחילת שנות התשעים, הגיטריסט ג׳ון פרושיאנטה עזב, ונפל להתמכרות קשה שכמעט עלתה לו בחייו. ב־1998 הוא חזר ללהקה, נקי ובריא, ו־Californication, שיצא בקיץ 1999, היה האלבום הראשון שלהם יחד מזה שמונה שנים. הוא נמכר ביותר מחמישה עשר מיליון עותקים והפך לאלבום המצליח ביותר שלהם.''',
'''את האלבום הפיק ריק רובין, והצליל כאן מלודי, בוגר ומהורהר יותר מבעבר: הפאנק המקפיץ עדיין שם, אבל לצידו יש בלדות רכות, גיטרות עדינות של פרושיאנטה והרמוניות קוליות יפות. השירים עוסקים בהתמכרות, בגמילה, במוות ובחיים בקליפורניה. Scar Tissue, שזכה בגראמי, הוא שיר רגוע ויפה, עם גיטרה מחליקה ומלודיה עצובה, על החיים אחרי הכאב. Californication, השיר שנתן לאלבום את שמו, הוא שיר נוגה ומלודי על הצד האפל של הוליווד ושל תעשיית הבידור. Otherside הוא שיר מהורהר על המאבק בהתמכרות, עם פזמון שנכנס ללב.''',
'''Californication נחשב לאחד האלבומים החשובים של הרוק בסוף שנות התשעים, והחזיר את הלהקה לפסגה. השירים שלו עדיין מושמעים ברדיו בכל העולם. הוא ספג גם ביקורת על הסאונד, שנדחס ונעשה רועש מאוד בשלב העיבוד הסופי, כדוגמה ל"מלחמת העוצמה" של התקופה.''',
'''שמעו את Scar Tissue, ושימו לב לגיטרה העדינה של פרושיאנטה. והשוו ל־Make Yourself של אינקובוס (אלבום 883), להקה צעירה שגדלה על המוזיקה שלהם.''',
], [
('Scar Tissue', 'שיר רגוע ויפה עם גיטרה מחליקה, על החיים אחרי הכאב.'),
('Californication', 'שיר נוגה ומלודי על הצד האפל של הוליווד.'),
('Otherside', 'שיר מהורהר על המאבק בהתמכרות, עם פזמון שנכנס ללב.'),
])
